window.BANK=window.BANK||{};window.BANK["6742"]={"n":"第五章 资本主义的发展及其趋势","qs":[{"i":"144285","t":"单选","q":"全球领先的某跨国算力巨头凭借其在芯片架构领域的绝对垄断地位，将其算力租赁价格长期维持在历史高位，获取了远超行业平均水平的利润。垄断利润归根结底来自()","o":{"A":"A.垄断组织对雇佣工人和非垄断企业所创造的剩余价值","B":"B.垄断组织凭借其市场支配地位对商品价值进行的创造","C":"C.垄断组织通过先进的管理手段对生产成本的极端压缩","D":"D.垄断组织利用技术优势对市场风险进行的全面性对冲"},"a":"A","j":"<p>全球领先的某跨国算力巨头凭借其在芯片架构领域的绝对垄断地位，将其算力租赁价格长期维持在历史高位，获取了远超行业平均水平的利润。<span style=\"background-color: #f8cac6; color: #000000;\">垄断利润归根结底</span><strong>来自</strong>()</p>\n<p>A.垄断组织对雇佣工人和非垄断企业所创造的剩余价值&radic;</p>\n<p>B.垄断组织凭借其市场支配地位对商品价值进行的<strong>创造</strong> <span style=\"background-color: #f8cac6; color: #000000;\">垄断组织不会自己创造</span></p>\n<p>C.垄断组织通过先进的管理手段对生产成本的极端压缩 <span style=\"background-color: #f8cac6; color: #000000;\">不合题意</span></p>\n<p>D.垄断组织利用技术优势对市场风险进行的全面性对冲 <span style=\"background-color: #f8cac6; color: #000000;\">不合题意</span></p>\n<p>【答案】A<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">垄断利润本质上是剩余价值的转化形式，其来源包括：本企业工人的剩余价值、非垄断企业的部分剩余价值、小生产者的一部分价值以及通过财政补贴等方式再分配的国民收入。</span></p>","k":"考点78 资本主义从自由竞争到垄断","kid":"141","r":22465,"tot":28700},{"i":"144286","t":"单选","q":"国家垄断资本主义的产生是资本主义基本矛盾发展的必然结果。2026年全球半导体产业链的“政府主导型并购潮”表明，国家垄断资本主义在实质上()","o":{"A":"A.彻底消除了资本主义经济运行中的盲目性和无政府状态","B":"B.标志着资本主义私有制性质已经发生了根本性的质变","C":"C.是垄断资本利用国家机器获取高额垄断利润的工具","D":"D.能够从根本上解决生产社会化与私有制之间的冲突"},"a":"C","j":"<p>国家垄断资本主义的产生是资本主义基本矛盾发展的必然结果。<span style=\"color: #e03e2d;\">||</span>2026年全球半导体产业链的&ldquo;政府主导型并购潮&rdquo;<strong>表明</strong>，<span style=\"background-color: #f8cac6; color: #000000;\">国家垄断资本主义在实质上</span>()</p>\n<p>A.<strong>彻底消除了</strong>资本主义经济运行中的盲目性和无政府状态 <span style=\"background-color: #f8cac6; color: #000000;\">绝对表述K错误</span></p>\n<p>B.标志着资本主义私有制性质<strong>已经发生了根本性的质变 </strong><span style=\"background-color: #f8cac6; color: #000000;\">绝对表述和第一梯队K错误</span></p>\n<p>C.是垄断资本利用国家机器获取高额垄断利润的工具&radic;</p>\n<p>D.能够<strong>从根本上解决</strong>生产社会化与私有制之间的冲突 <span style=\"background-color: #f8cac6; color: #000000;\">绝对表述K错误</span></p>\n<p>【答案】C<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">国家垄断资本主义虽然有一定的调节作用，但本质上是为垄断资本服务的，不能从根本上消除基本矛盾。</span></p>","k":"考点79 国家垄断资本主义的形成及作用","kid":"142","r":25343,"tot":27184},{"i":"144287","t":"单选","q":"随着《全球数字贸易便利化协定》正式生效，数据要素在全球范围内的流动效率大幅提升，资本在数字空间的配置趋于极致。经济全球化的本质是()","o":{"A":"A.资源在全球范围内的优化配置和人类文明的共同进步","B":"B.生产力发展的客观要求和资本在全球范围内的扩张","C":"C.发达国家通过技术霸权实现对发展中国家的直接吞并","D":"D.各国经济在完全平等的基础上实现的利益深度互补"},"a":"B","j":"<p>随着《全球数字贸易便利化协定》正式生效，数据要素在全球范围内的流动效率大幅提升，资本在数字空间的配置趋于极致。<span style=\"color: #e03e2d;\">Ⅱ</span><span style=\"background-color: #f8cac6; color: #000000;\">经济全球化的本质</span><strong>是</strong>()</p>\n<p>A.资源在全球范围内的优化配置和人类文明的<strong>共同进步 </strong><span style=\"background-color: #f8cac6; color: #000000;\">过于理想化</span></p>\n<p>B.生产力发展的客观要求和资本在全球范围内的扩张&radic;</p>\n<p>C.发达国家通过技术霸权实现对发展中国家的<strong>直接吞并 </strong><span style=\"background-color: #f8cac6; color: #000000;\">绝对表述错误</span></p>\n<p>D.各国经济在<strong>完全平等</strong>的基础上实现的利益深度互补 <span style=\"background-color: #f8cac6; color: #000000;\">绝对表述错误</span></p>\n<p>【答案】B<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">经济全球化是生产力发展的客观要求，本质是资本扩张。</span></p>","k":"考点84 经济全球化及其影响","kid":"151","r":19731,"tot":27685},{"i":"144288","t":"单选","q":"马克思指出：“资产阶级在它的不到一百年的阶级统治中所创造的生产力，比过去一切世代创造的全部生产力还要多、还要大。”但资本主义在推动进步的同时也伴随着深刻的异化。这表明资本主义()","o":{"A":"A.是人类历史上最完美且无法被超越的社会形态","B":"B.随着生产社会化的提高，其私有制外壳会愈发成为发展的桎梏","C":"C.已经通过自我调节彻底克服了导致社会更替的矛盾根源","D":"D.在不同的历史阶段中，其进步性始终远大于其自身的局限性"},"a":"B","j":"<p>马克思指出：&ldquo;资产阶级在它的不到一百年的阶级统治中所创造的生产力，比过去一切世代创造的全部生产力还要多、还要大。&rdquo;但资本主义在推动进步的同时也伴随着深刻的异化。这<strong>表明</strong><span style=\"background-color: #f8cac6; color: #000000;\">资本主义</span>()</p>\n<p>A.是人类历史上<strong>最完美</strong>且无法被超越的社会形态 <span style=\"background-color: #f8cac6; color: #000000;\">表述错误</span></p>\n<p>B.随着生产社会化的提高，其私有制外壳会愈发成为发展的桎梏&radic;</p>\n<p>C.已经通过<strong>自我调节彻底克服</strong>了导致社会更替的<strong>矛盾根源 </strong><span style=\"background-color: #f8cac6; color: #000000;\">资本主义矛盾无法通过自身调节而克服</span></p>\n<p>D.在不同的历史阶段中，其<strong>进步性始终远大于其自身的局限性 </strong><span style=\"background-color: #f8cac6; color: #000000;\">表述错误</span></p>\n<p>【答案】B<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">资本主义起过进步作用，但随着生产力发展，其私有制局限性凸显，符合&ldquo;阶梯式递进、不断发展进步&rdquo;的历史逻辑。</span></p>","k":"考点89 资本主义的历史地位","kid":"719","r":24775,"tot":26504},{"i":"144289","t":"单选","q":"在资本主义生产发展和生产规模不断扩大的过程中，生产和资本不断集中。生产集中是指生产资料、劳动力和商品的生产日益集中于少数大企业的过程，其结果是()","o":{"A":"A.资本主义经济危机的频繁爆发","B":"B.资本主义社会失业现象产生","C":"C.越来越多的资本为少数大资本家所支配","D":"D.大企业在整个社会生产中所占的比重不断增加"},"a":"D","j":"<p>在资本主义生产发展和生产规模不断扩大的过程中，生产和资本不断集中。<span style=\"color: #e03e2d;\">||</span><span style=\"background-color: #f8cac6; color: #000000;\">生产集中</span>是指生产资料、劳动力和商品的生产日益集中于少数大企业的过程，<strong>其结果是</strong>()</p>\n<p>A.资本主义经济危机的频繁爆发 <span style=\"background-color: #f8cac6; color: #000000;\">根本原因是资本主义的基本矛盾</span></p>\n<p>B.资本主义社会失业现象产生 <span style=\"background-color: #f8cac6; color: #000000;\">资本积累是资本主义失业现象产生的根源</span></p>\n<p>C.越来越多的资本为少数大资本家所支配 <span style=\"background-color: #f8cac6; color: #000000;\">资本集中的结果</span></p>\n<p>D.大企业在整个<strong>社会生产中</strong>所占的比重不断增加&radic;</p>\n<p>【答案】D<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">对应词：生产。生产集中是指生产资料、劳动力和商品的生产日益集中于少数大企业的过程，其结果是大企业在整个社会生产中所占的比重不断增加。</span></p>","k":"考点78 资本主义从自由竞争到垄断","kid":"141","r":9751,"tot":29548},{"i":"144290","t":"单选","q":"列宁曾指出，集中发展到一定阶段，可以说自然而然地走向垄断。因为几十个大型企业彼此容易达成协定；另一方面，正是企业的规模巨大造成了竞争的困难，产生了垄断的趋势。垄断组织的形式多种多样，且不断变化发展，但是它们在本质上都是()","o":{"A":"A.国家通过多种形式参与私人垄断资本的再生产过程","B":"B.通过“参与制”实现的","C":"C.通过联合实现独占和瓜分市场来操纵垄断价格以攫取高额垄断利润","D":"D.通过金融联系和资本参与将银行垄断资本和工业垄断资本融合在一起"},"a":"C","j":"<p>列宁曾指出，集中发展到一定阶段，可以说自然而然地走向垄断。因为几十个大型企业彼此容易达成协定；另一方面，正是企业的规模巨大造成了竞争的困难，产生了垄断的趋势。<span style=\"color: #e03e2d;\">||</span><span style=\"background-color: #f8cac6; color: #000000;\">垄断组织的形式</span>多种多样，且不断变化发展，但是它们<strong>在本质上都是</strong>()</p>\n<p>A.国家通过多种形式参与私人垄断资本的再生产过程 <span style=\"background-color: #f8cac6; color: #000000;\">这是国家垄断资本主义的主要形式之一，不合题意</span></p>\n<p>B.通过&ldquo;参与制&rdquo;实现的 <span style=\"background-color: #f8cac6; color: #000000;\">这是金融寡头在经济领域的统治方式</span></p>\n<p>C.通过联合实现独占和瓜分市场来操纵垄断价格以攫取高额垄断利润&radic;</p>\n<p>D.通过金融联系和资本参与将银行垄断资本和工业垄断资本融合在一起 <span style=\"background-color: #f8cac6; color: #000000;\">金融资本</span></p>\n<p>【答案】C<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">垄断组织在本质上都是通过联合实现独占和瓜分市场来操纵垄断价格以攫取高额垄断利润，口诀记忆为&ldquo;连战分利&rdquo;。</span></p>","k":"考点78 资本主义从自由竞争到垄断","kid":"141","r":23229,"tot":26140},{"i":"144291","t":"单选","q":"资本主义的发展经历了两个阶段：自由竞争资本主义和垄断资本主义。垄断是通过一定的垄断组织形式实现的。垄断组织是指在一个或几个经济部门中占据垄断地位的大企业联合。垄断组织的形式多种多样，而且在各个国家、各个时期也不同。最简单的、初级的垄断组织形式是()","o":{"A":"A.短期价格协定","B":"B.国际卡特尔","C":"C.国际货币基金组织","D":"D.国家垄断资本主义的国际联盟"},"a":"A","j":"<p>资本主义的发展经历了两个阶段：自由竞争资本主义和垄断资本主义。垄断是通过一定的垄断组织形式实现的。垄断组织是指在一个或几个经济部门中占据垄断地位的大企业联合。垄断组织的形式多种多样，而且在各个国家、各个时期也不同。<span style=\"color: #e03e2d;\">|</span><span style=\"background-color: #f8cac6; color: #000000;\">最简单的、初级的垄断组织形式</span><strong>是</strong>()</p>\n<p>A.短期价格协定&radic;</p>\n<p>B.国际卡特尔 <span style=\"background-color: #f8cac6; color: #000000;\">早期的国际垄断同盟，口诀记忆为&ldquo;早国盟&rdquo;</span></p>\n<p>C.国际货币基金组织 <span style=\"background-color: #f8cac6; color: #000000;\">从事国际经济协调、维护国际经济秩序的国际性协调组织</span></p>\n<p>D.国家垄断资本主义的国际联盟 <span style=\"background-color: #f8cac6; color: #000000;\">当代国际垄断同盟的形式，口诀记忆为&ldquo;待嫁国盟&rdquo;</span></p>\n<p>【答案】A<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">最简单的、初级的垄断组织形式是短期价格协定，口诀记忆为&ldquo;简短&rdquo;。</span></p>","k":"考点78 资本主义从自由竞争到垄断","kid":"141","r":16948,"tot":27018},{"i":"144292","t":"单选","q":"列宁在《帝国主义是资本主义的最高阶段》中指出：帝国主义，或者说金融资本的统治，是资本主义的最高阶段，这时候，这种分离达到了极大的程度。金融资本对其他一切形式的资本的优势，意味着食利者和金融寡头占统治地位，意味着少数拥有金融“实力”的国家处于和其余一切国家不同的特殊地位。金融寡头对国家机器的控制主要是()","o":{"A":"A.通过“参与制”实现的","B":"B.控制跨国公司","C":"C.通过同政府的“个人联合”来实现的","D":"D.建立政策咨询机构"},"a":"C","j":"<p>列宁在《帝国主义是资本主义的最高阶段》中指出：帝国主义，或者说金融资本的统治，是资本主义的最高阶段，这时候，这种分离达到了极大的程度。金融资本对其他一切形式的资本的优势，意味着食利者和金融寡头占统治地位，意味着少数拥有金融&ldquo;实力&rdquo;的国家处于和其余一切国家不同的特殊地位。<span style=\"color: #e03e2d;\">||</span><span style=\"background-color: #f8cac6; color: #000000;\">金融寡头对国家机器的控制</span><strong>主要是</strong>()</p>\n<p>A.通过&ldquo;参与制&rdquo;实现的 <span style=\"background-color: #f8cac6; color: #000000;\">金融寡头在经济领域中的统治</span></p>\n<p>B.控制跨国公司 <span style=\"background-color: #f8cac6; color: #000000;\">无此表述</span></p>\n<p>C.通过同政府的&ldquo;个人联合&rdquo;来实现的&radic;</p>\n<p>D.建立政策咨询机构<span style=\"background-color: #f8cac6; color: #000000;\"> 影响内政外交与社会生活</span></p>\n<p>【答案】C<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">金融寡头对国家机器的控制主要是通过同政府的&ldquo;个人联合&rdquo;来实现的。</span></p>","k":"考点78 资本主义从自由竞争到垄断","kid":"141","r":15512,"tot":27527},{"i":"144293","t":"单选","q":"垄断资本的实质在于获取垄断利润，垄断利润的形成，关键在于垄断组织在经济生活中起了决定性作用。垄断资本所获得的高额利润，归根到底来自()","o":{"A":"A.生产集中和资本集中","B":"B.无产阶级和其他劳动人民所创造的剩余价值","C":"C.通过垄断高价和垄断低价来控制市场","D":"D.通过资本主义国家政权进行有利于垄断资本的再分配"},"a":"B","j":"<p>垄断资本的实质在于获取垄断利润，垄断利润的形成，关键在于垄断组织在经济生活中起了决定性作用。<span style=\"background-color: #f8cac6; color: #000000;\">垄断资本所获得的高额利润</span>，<strong>归根到底来自</strong>()</p>\n<p>A.生产集中和资本集中 <span style=\"background-color: #f8cac6; color: #000000;\">是资本家追求剩余价值的结果，发展到一定阶段必然引起垄断</span></p>\n<p>B.无产阶级和其他劳动人民所创造的剩余价值&radic;</p>\n<p>C.通过垄断高价和垄断低价来控制市场 <span style=\"background-color: #f8cac6; color: #000000;\">属于垄断利润具体来源，不是归根到底</span></p>\n<p>D.通过资本主义国家政权进行有利于垄断资本的再分配<span style=\"background-color: #f8cac6; color: #000000;\"> 属于垄断利润具体来源，不是归根到底</span></p>\n<p>【答案】B<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">垄断资本所获得的高额利润，归根到底来自无产阶级和其他劳动人民所创造的剩余价值。</span></p>","k":"考点78 资本主义从自由竞争到垄断","kid":"141","r":20195,"tot":26221},{"i":"144294","t":"单选","q":"列宁根据他所处时代的时间曾指出，资本主义发展到垄断资本主义，进而发展到帝国主义，便具有其基本特征。垄断利润的形成，关键在于经济生活中起了决定性作用的()","o":{"A":"A.金融寡头","B":"B.跨国公司","C":"C.资本输出","D":"D.垄断组织"},"a":"D","j":"<p>列宁根据他所处时代的时间曾指出，资本主义发展到垄断资本主义，进而发展到帝国主义，便具有其基本特征。<span style=\"color: #e03e2d;\">|</span><span style=\"background-color: #f8cac6; color: #000000;\">垄断利润的形成，关键</span>在于<strong>经济生活中起了决定性作用的</strong>()</p>\n<p>A.金融寡头 <span style=\"background-color: #f8cac6; color: #000000;\">不合题意</span></p>\n<p>B.跨国公司 <span style=\"background-color: #f8cac6; color: #000000;\">不合题意</span></p>\n<p>C.资本输出 <span style=\"background-color: #f8cac6; color: #000000;\">不合题意</span></p>\n<p>D.垄断组织&radic;</p>\n<p>【答案】D<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">垄断利润的形成，关键在于垄断组织在经济生活中起了决定性作用，从而阻碍了资本在各部门之间的自由转移，限制了利润平均化的趋势，这样一来，垄断资本家有可能长期获得大大超过平均利润的垄断利润。</span></p>","k":"考点78 资本主义从自由竞争到垄断","kid":"141","r":18221,"tot":26464},{"i":"144295","t":"单选","q":"早在第一次世界大战期间，资本主义交战国的政府就借助国家的力量扩军备战，推行国民经济军事化，普遍加强了国家对社会经济和人民生活的统治和管理，对全部生产实行最严格的统计和监督，国家垄断资本主义由此得以产生。对此，列宁曾指出：“以自由竞争为基础的旧资本主义已被这场战争彻底摧毁，它已经让位于国家垄断资本主义。”这说明国家垄断资本主义的出现()","o":{"A":"A.标志着资本主义发展进入了新的阶段","B":"B.是资本主义生产关系的质变","C":"C.使国际市场上的竞争越来越激烈","D":"D.对资本主义经济的发展产生了积极的作用"},"a":"A","j":"<p>早在第一次世界大战期间，资本主义交战国的政府就借助国家的力量扩军备战，推行国民经济军事化，普遍加强了国家对社会经济和人民生活的统治和管理，对全部生产实行最严格的统计和监督，国家垄断资本主义由此得以产生。对此，列宁曾指出：&ldquo;以<span style=\"background-color: #f8cac6; color: #000000;\">自由竞争为基础的旧资本主义已被这场战争彻底摧毁</span>，它已经让位于国家垄断资本主义。&rdquo;<span style=\"color: #e03e2d;\">||</span>这<strong>说明</strong><span style=\"background-color: #f8cac6; color: #000000;\">国家垄断资本主义</span><strong>的出现</strong>()</p>\n<p>A.标志着资本主义发展进入了新的阶段&radic; <span style=\"background-color: #f8cac6; color: #000000;\">即帝国主义阶段</span></p>\n<p>B.是资本主义生产关系的<strong>质变</strong> <span style=\"background-color: #f8cac6; color: #000000;\">如果是资本主义生产关系的质变，那就是走向社会主义了，国家垄断资本主义的产生，是垄断资本主义生产关系在自身范围内的部分质变</span></p>\n<p>C.使国际市场上的竞争越来越激烈 <span style=\"background-color: #f8cac6; color: #000000;\">是垄断条件下竞争新特点，不合题意</span></p>\n<p>D.对资本主义经济的发展产生了积极的作用 <span style=\"background-color: #f8cac6; color: #000000;\">这是国家垄断资本主义的影响，不合题意</span></p>\n<p>【答案】A<span style=\"background-color: #f8cac6; color: #000000;\">材料思考题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">国家垄断资本主义的出现标志着资本主义发展进入了帝国主义阶段。</span></p>","k":"考点79 国家垄断资本主义的形成及作用","kid":"142","r":20210,"tot":25710},{"i":"144296","t":"单选","q":"国家干预深入资本主义的生产、流通、分配和消费的各个环节，国家垄断资本主义是垄断资本主义的新发展，它对资本主义经济的发展产生了积极作用。但是，国家垄断资本主义的出现并没有根本改变垄断资本主义的性质，也没有从根本上消除资本主义的基本矛盾。国家垄断资本主义的实质是()","o":{"A":"A.国家与私人共有、合营企业","B":"B.私人垄断资本利用国家机器来为其服务、获取垄断利润的手段","C":"C.国家通过多种形式参与私人垄断资本的再生产过程","D":"D.国家运用财政政策、货币政策等经济手段，对社会总供求进行调节"},"a":"B","j":"<p>国家干预深入资本主义的生产、流通、分配和消费的各个环节，国家垄断资本主义是垄断资本主义的新发展，它对资本主义经济的发展产生了积极作用。但是，国家垄断资本主义的出现并没有根本改变垄断资本主义的性质，也没有从根本上消除资本主义的基本矛盾。<span style=\"color: #e03e2d;\">|</span><span style=\"background-color: #f8cac6; color: #000000;\">国家垄断资本主义</span>的<strong>实质是</strong>()</p>\n<p>A.国家与私人共有、合营企业 <span style=\"background-color: #f8cac6; color: #000000;\">是国家垄断资本主义的形式</span></p>\n<p>B.私人垄断资本利用国家机器来为其服务、获取垄断利润的手段&radic;</p>\n<p>C.国家通过多种形式参与私人垄断资本的再生产过程 <span style=\"background-color: #f8cac6; color: #000000;\">是国家垄断资本主义的形式</span></p>\n<p>D.国家运用财政政策、货币政策等经济手段，对社会总供求进行调节 <span style=\"background-color: #f8cac6; color: #000000;\">是国家垄断资本主义的形式</span></p>\n<p>【答案】B<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">国家垄断资本主义的实质是私人垄断资本利用国家机器来为其服务、获取垄断利润的手段。</span></p>","k":"考点79 国家垄断资本主义的形成及作用","kid":"142","r":18805,"tot":25620},{"i":"144297","t":"单选","q":"国际垄断同盟在经济上瓜分世界是通过垄断组织间的协议实现的，而协议的订立、瓜分的结果又以经济实力为后盾和基础。由于各国经济发展总是不平衡的，这种从经济上瓜分世界的趋势还将不断持续下去。早期的国际垄断同盟主要是()","o":{"A":"A.短期价格协定","B":"B.国家垄断资本主义的国际联盟","C":"C.国际卡特尔","D":"D.国际货币基金组织"},"a":"C","j":"<p>国际垄断同盟在经济上瓜分世界是通过垄断组织间的协议实现的，而协议的订立、瓜分的结果又以经济实力为后盾和基础。由于各国经济发展总是不平衡的，这种从经济上瓜分世界的趋势还将不断持续下去。<span style=\"color: #e03e2d;\">|</span><span style=\"background-color: #f8cac6; color: #000000;\">早期的国际垄断同盟</span><strong>主要是</strong>()</p>\n<p>A.短期价格协定 <span style=\"background-color: #f8cac6; color: #000000;\">最简单、初级的垄断组织形式</span></p>\n<p>B.国家垄断资本主义的国际联盟 <span style=\"background-color: #f8cac6; color: #000000;\">当代国际垄断同盟的形式</span></p>\n<p>C.国际卡特尔&radic;</p>\n<p>D.国际货币基金组织 <span style=\"background-color: #f8cac6; color: #000000;\">从事国际经济协调、维护国际经济秩序的国际性协调组织</span></p>\n<p>【答案】C<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">早期的国际垄断同盟主要是国际卡特尔。</span></p>","k":"考点82 垄断资本国际化条件的垄断组织","kid":"149","r":18786,"tot":25680},{"i":"144298","t":"单选","q":"在经济全球化过程中，国际水平分工逐渐取代国际垂直分工，成为居主导地位的分工形式。这种分工的前提是()","o":{"A":"A.跨国界组织","B":"B.全球化生产体系的形成和建立","C":"C.资本、技术、管理技能等生产要素的跨国流动","D":"D.贸易和金融的全球化"},"a":"C","j":"<p>在经济全球化过程中，<span style=\"background-color: #f8cac6; color: #000000;\">国际水平分工</span>逐渐取代国际垂直分工，成为居主导地位的分工形式。<span style=\"color: #e03e2d;\">|</span>这种分工的<strong>前提是</strong>()</p>\n<p>A.跨国界组织 <span style=\"background-color: #f8cac6; color: #000000;\">这是生产全球化的核心</span></p>\n<p>B.全球化生产体系的形成和建立 <span style=\"background-color: #f8cac6; color: #000000;\">这是生产全球化的标志</span></p>\n<p>C.资本、技术、管理技能等生产要素的跨国流动&radic;</p>\n<p>D.贸易和金融的全球化 <span style=\"background-color: #f8cac6; color: #000000;\">这是全球化的表现</span></p>\n<p>【答案】C<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">国际水平分工的前提是资本、技术、管理技能等生产要素的跨国流动。</span></p>","k":"考点84 经济全球化及其影响","kid":"151","r":15696,"tot":26457},{"i":"144299","t":"单选","q":"20世纪90年代以来，一些传统的计划经济国家纷纷放弃计划经济体制，转而向市场经济体制过渡。在国际范围内，随着国际货币基金组织、世界银行、世界贸易组织等国际经济组织的成立，各成员国对本国或本地区市场的控制大大放松，贸易自由化和投资自由化的进程不断加快。这说明为经济全球化迅猛发展提供体制与组织保障的是()","o":{"A":"A.各国经济体制的变革和国际经济组织的发展","B":"B.跨国公司的发展","C":"C.科学技术的进步和生产力的发展","D":"D.生产全球化、贸易全球化、金融全球化"},"a":"A","j":"<p>20世纪90年代以来，一些传统的计划经济国家纷纷放弃计划经济体制，转而向市场经济体制过渡。在国际范围内，随着国际货币基金组织、世界银行、世界贸易组织等国际经济组织的成立，各成员国对本国或本地区市场的控制大大放松，贸易自由化和投资自由化的进程不断加快。<span style=\"color: #e03e2d;\">|</span>这<strong>说明</strong><span style=\"background-color: #f8cac6; color: #000000;\">为经济全球化迅猛发展提供体制与组织保障</span>的是()</p>\n<p>A.各国经济体制的变革和国际经济组织的发展&radic;</p>\n<p>B.跨国公司的发展 <span style=\"background-color: #f8cac6; color: #000000;\">跨国公司的发展为经济全球化提供了适宜的企业组织形式</span></p>\n<p>C.科学技术的进步和生产力的发展 <span style=\"background-color: #f8cac6; color: #000000;\">为经济全球化提供了坚实的物质基础和根本的推动力</span></p>\n<p>D.生产全球化、贸易全球化、金融全球化 <span style=\"background-color: #f8cac6; color: #000000;\">这是经济全球化的表现</span></p>\n<p>【答案】A<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">经济全球化迅猛发展提供体制与组织保障的是各国经济体制的变革和国际经济组织的发展。</span></p>","k":"考点84 经济全球化及其影响","kid":"151","r":18495,"tot":25356},{"i":"144300","t":"单选","q":"进入21世纪以来，随着经济全球化的深入发展，新一轮科技革命和产业变革进入空前密集活跃期，社会化大生产在世界范围内更大规模、更广范围、更深层次展开，世界格局深度调整，资本主义又呈现出一些新变化新特征。当代资本主义最突出、最鲜明、最主要的特征是()","o":{"A":"A.国际金融资本的垄断","B":"B.社会阶级层次结构呈现复杂性多样化","C":"C.科技创新加速资本主义生产方式变化","D":"D.发达资本主义国家在世界范围内推行霸权主义和强权政治"},"a":"A","j":"<p><span style=\"background-color: #f8cac6; color: #000000;\">进入21世纪以来</span>，随着经济全球化的深入发展，新一轮科技革命和产业变革进入空前密集活跃期，社会化大生产在世界范围内更大规模、更广范围、更深层次展开，世界格局深度调整，资本主义又呈现出一些新变化新特征。<span style=\"background-color: #f8cac6; color: #000000;\">当代资本主义最突出、最鲜明、最主要的特征</span><strong>是</strong>()</p>\n<p>A.国际金融资本的垄断&radic;</p>\n<p>B.社会阶级层次结构呈现复杂性多样化</p>\n<p>C.科技创新加速资本主义生产方式变化</p>\n<p>D.发达资本主义国家在世界范围内推行霸权主义和强权政治 <span style=\"background-color: #f8cac6; color: #000000;\">BCD属于21世纪以来，当代资本主义变化的新特征，但并不是最鲜明、最主要的特征</span></p>\n<p>【答案】A<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">当代资本主义最突出、最鲜明、最主要的特征是国际金融资本的垄断。</span></p>","k":"考点87 当代资本主义变化的新特征","kid":"156","r":13971,"tot":26141},{"i":"144301","t":"单选","q":"进入21世纪以来，随着经济全球化的深入发展，新一轮科技革命和产业变革进入空前密集活跃期，社会化大生产在世界范围内更大规模、更广范围、更深层次展开，世界格局深度调整，资本主义又呈现出一些新变化新特征。但这些新变化新特征，并未()","o":{"A":"A.改变资本主义的经济基础和追求利润最大化的本性","B":"B.放大资本主义的系统性危机","C":"C.暴露资本主义的弊端与困境","D":"D.诱发更激烈的世界性问题和全球性矛盾"},"a":"A","j":"<p><span style=\"background-color: #f8cac6; color: #000000;\">进入21世纪以来</span>，随着经济全球化的深入发展，新一轮科技革命和产业变革进入空前密集活跃期，社会化大生产在世界范围内更大规模、更广范围、更深层次展开，世界格局深度调整，资本主义又呈现出一些新变化新特征。<span style=\"color: #e03e2d;\">||</span>但这些<span style=\"background-color: #f8cac6; color: #000000;\">新变化新特征</span>，<strong>并未</strong>()</p>\n<p>A.改变资本主义的经济基础和追求利润最大化的本性&radic;</p>\n<p>B.放大资本主义的系统性危机</p>\n<p>C.暴露资本主义的弊端与困境</p>\n<p>D.诱发更激烈的世界性问题和全球性矛盾</p>\n<p><span style=\"background-color: #f8cac6; color: #000000;\">BCD:表述错误，21世纪以来资本主义的新变化，在拓展资本主义发展空间的同时，也放大了资本主义的系统性危机，不断暴露资本主义的弊端与困境，不断诱发更激烈的世界性问题和全球性矛盾，也不断引发世界范围内对资本主义制度和价值观的质疑</span></p>\n<p>【答案】A<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">新变化新特征，并未改变资本主义的经济基础和追求利润最大化的本性。</span></p>","k":"考点87 当代资本主义变化的新特征","kid":"156","r":23133,"tot":24130},{"i":"144302","t":"单选","q":"从人类社会发展的长河看，资本主义终究要被社会主义所取代，这是历史发展的基本趋势。资本主义的内在矛盾决定了资本主义必然被社会主义所代替。在资本主义的内在矛盾中，成为社会主义前奏的是()","o":{"A":"A.资本主义基本矛盾","B":"B.资本积累","C":"C.资产阶级和无产阶级的矛盾斗争","D":"D.国家垄断资本主义"},"a":"D","j":"<p>从人类社会发展的长河看，资本主义终究要被社会主义所取代，这是历史发展的基本趋势。资本主义的内在矛盾决定了资本主义必然被社会主义所代替。在<span style=\"background-color: #f8cac6; color: #000000;\">资本主义的内在矛盾</span>中，<strong>成为社会主义前奏的是</strong>()</p>\n<p>A.资本主义基本矛盾 <span style=\"background-color: #f8cac6; color: #000000;\">资本主义基本矛盾&ldquo;包含着现代的一切冲突的萌芽&rdquo;</span></p>\n<p>B.资本积累 <span style=\"background-color: #f8cac6; color: #000000;\">资本积累推动资本主义基本矛盾不断激化并最终否定资本主义自身</span></p>\n<p>C.资产阶级和无产阶级的矛盾斗争 <span style=\"background-color: #f8cac6; color: #000000;\">阶级斗争是阶级社会发展的直接动力</span></p>\n<p>D.国家垄断资本主义&radic;</p>\n<p>【答案】D<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">国家垄断资本主义是资本社会化的更高形式，将成为社会主义的前奏。</span></p>","k":"考点89 资本主义的历史地位","kid":"719","r":10798,"tot":26665},{"i":"144303","t":"单选","q":"马克思在《资本论》中指出：“生产资料的集中和劳动的社会化，达到了同他们的资本主义外壳不能相容的地步。这个外壳就要炸毁了。资本主义私有制的丧钟就要响了。剥夺者就要被剥夺了。”这表明()","o":{"A":"A.资本主义基本矛盾在资本积累中会不断激化直至爆发","B":"B.国家垄断资本主义是资本社会化的更高形式","C":"C.资本主义经济危机的爆发不可避免","D":"D.资本主义社会存在着两大阶级之间的矛盾和斗争"},"a":"A","j":"<p>马克思在《资本论》中指出：&ldquo;<span style=\"background-color: #f8cac6; color: #000000;\">生产资料的集中和劳动的社会化</span>，达到了同他们的资本主义外壳<span style=\"background-color: #f8cac6; color: #000000;\">不能相容的地步</span>。这个外壳就要炸毁了。资本主义私有制的丧钟就要响了。<span style=\"color: #e03e2d;\">|</span>剥夺者就要被剥夺了。&rdquo;这<strong>表明</strong>()</p>\n<p>A.资本主义基本矛盾在资本积累中会不断激化直至爆发&radic;</p>\n<p>B.国家垄断资本主义是资本社会化的更高形式</p>\n<p>C.资本主义经济危机的爆发不可避免</p>\n<p>D.资本主义社会存在着两大阶级之间的矛盾和斗争 <span style=\"background-color: #f8cac6; color: #000000;\">BCD不合题意</span></p>\n<p>【答案】A<span style=\"background-color: #f8cac6; color: #000000;\">材料思考题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">生产资料资本主义私有制同生产社会化之间的矛盾是资本主义基本矛盾，符合&ldquo;生产资料的集中和劳动的社会化达到了不相容的地步&rdquo;。</span></p>","k":"考点72 资本积累★★","kid":"712","r":18636,"tot":24855},{"i":"144304","t":"多选","q":"在资本主义发展的历史长河中，国家垄断资本主义的出现并非偶然。全球半导体补贴政策的盛行证明了国家垄断资本主义的产生是()","o":{"A":"A.科学技术进步和生产社会化高度发展的要求","B":"B.资本主义基本矛盾进一步尖锐化的必然结果","C":"C.资产阶级为了挽救资本主义制度而采取的被迫举措","D":"D.资本主义向社会主义阶段跨越的自发过渡形式"},"a":"ABC","j":"<p>在资本主义发展的历史长河中，国家垄断资本主义的出现并非偶然。Ⅱ全球半导体补贴政策的盛行证明了<span style=\"background-color: #f8cac6; color: #000000;\">国家垄断资本主义的产生</span><strong>是</strong>()</p>\n<p>A.科学技术进步和生产社会化高度发展的要求&radic;</p>\n<p>B.资本主义基本矛盾进一步尖锐化的必然结果&radic;</p>\n<p>C.资产阶级为了挽救资本主义制度而采取的被迫举措&radic;</p>\n<p>D.资本主义<strong>向社会主义</strong>阶段跨越的<strong>自发过渡形式 </strong><span style=\"background-color: #f8cac6; color: #000000;\">其性质依然是资本主义，并未发生向社会主义的质变</span></p>\n<p>【答案】ABC<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">ABC对应了国家垄断资本主义产生的三大原因。</span></p>","k":"考点79 国家垄断资本主义的形成及作用","kid":"142","r":10801,"tot":25941},{"i":"144305","t":"多选","q":"所谓垄断，是指少数资本主义大企业为了获得高额利润，通过相互协议或联合，对一个或几个部门商品的生产、销售和价格进行操纵和控制。垄断产生的原因有(","o":{"A":"A.通过改进技术、提高劳动生产率等经济手段战胜对手","B":"B.企业规模巨大，形成对竞争的限制","C":"C.避免激烈的竞争带来严重的损失","D":"D.生产集中发展到相当高的程度"},"a":"BCD","j":"<p>所谓垄断，是指少数资本主义大企业为了获得高额利润，通过相互协议或联合，对一个或几个部门商品的生产、销售和价格进行操纵和控制。<span style=\"color: #e03e2d;\">||</span><span style=\"background-color: #f8cac6; color: #000000;\">垄断产生的原因</span><strong>有</strong>()</p>\n<p>A.通过改进技术、提高劳动生产率等经济手段战胜对手 <span style=\"background-color: #f8cac6; color: #000000;\">在自由竞争阶段，企业也可以通过改进技术、提高劳动生产率等经济手段战胜对手，并非垄断产生的原因</span></p>\n<p>B.企业规模巨大，形成对竞争的限制&radic;</p>\n<p>C.避免激烈的竞争带来严重的损失&radic;</p>\n<p>D.生产集中发展到相当高的程度&radic;</p>\n<p>【答案】BCD<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">垄断产生的原因有企业规模巨大，形成对竞争的限制；避免激烈的竞争带来严重的损失；生产集中发展到相当高的程度。</span></p>","k":"考点78 资本主义从自由竞争到垄断","kid":"141","r":7646,"tot":26822},{"i":"144306","t":"多选","q":"垄断是在自由竞争中形成的，是作为自由竞争的对立面产生的。垄断并不能消除竞争，反而使竞争变得更加复杂和剧烈。这是因为()","o":{"A":"A.垄断必须通过竞争来维持","B":"B.非垄断的企业之间不存在竞争","C":"C.垄断组织不能囊括一切商品生产","D":"D.垄断没有消除产生竞争的经济条件"},"a":"ACD","j":"<p>垄断是在自由竞争中形成的，是作为自由竞争的对立面产生的。<span style=\"background-color: #f8cac6; color: #000000;\">垄断并不能消除竞争</span>，反而使竞争变得更加复杂和剧烈。<span style=\"color: #e03e2d;\">|</span>这是<strong>因为</strong>()</p>\n<p>A.垄断必须通过竞争来维持&radic;</p>\n<p>B.非垄断的企业之间<strong>不存在竞争 </strong><span style=\"background-color: #f8cac6; color: #000000;\">基础知识错误，且不合题意</span></p>\n<p>C.垄断组织不能囊括一切商品生产&radic;</p>\n<p>D.垄断没有消除产生竞争的经济条件&radic;</p>\n<p>【答案】ACD<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">垄断必须通过竞争来维持，垄断组织不能囊括一切商品生产，垄断没有消除产生竞争的经济条件。</span></p>","k":"考点78 资本主义从自由竞争到垄断","kid":"141","r":19056,"tot":23571},{"i":"144307","t":"多选","q":"列宁指出，帝国主义最深厚的经济基础是垄断，但这种垄断不是纯粹的垄断，而是同竞争混合和并存的垄断。从自由竞争中成长起来的垄断，没有也不可能消除竞争。垄断条件下的竞争同自由竞争相比，具有的新特点有()","o":{"A":"A.除了采取各种形式的经济手段外，还采取非经济的手段","B":"B.竞争范围从经济领域扩大到经济以外的领域","C":"C.目的是为了获取高额垄断利润","D":"D.扩大了剩余价值产生的来源"},"a":"ABC","j":"<p>列宁指出，帝国主义最深厚的经济基础是垄断，但这种垄断不是纯粹的垄断，而是同竞争混合和并存的垄断。从自由竞争中成长起来的垄断，没有也不可能消除竞争。<span style=\"background-color: #f8cac6; color: #000000;\">垄断条件下的竞争同自由竞争</span>相比，具有的<strong>新特点有</strong>()</p>\n<p>A.除了采取各种形式的经济手段外，还采取非经济的手段&radic;</p>\n<p>B.竞争范围从经济领域扩大到经济以外的领域&radic;</p>\n<p>C.目的是为了获取高额垄断利润&radic;</p>\n<p>D.<strong>扩大了</strong>剩余价值产生的来源 <span style=\"background-color: #f8cac6; color: #000000;\">没有扩大，剩余劳动是剩余价值产生的唯一源泉</span></p>\n<p>【答案】ABC<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">垄断条件下的竞争除了采取各种形式的经济手段外，还采取非经济的手段；竞争范围从经济领域扩大到经济以外的领域；目的是为了获取高额垄断利润。</span></p>","k":"考点78 资本主义从自由竞争到垄断","kid":"141","r":14651,"tot":24515},{"i":"144308","t":"多选","q":"金融资本是由工业垄断资本和银行垄断资本融合在一起而形成的一种垄断资本。银行垄断资本和工业垄断资本能够密切地融合在一起，是通过()","o":{"A":"A.金融联系","B":"B.资本参与","C":"C.人事参与","D":"D.金融创新"},"a":"ABC","j":"<p>金融资本是由工业垄断资本和银行垄断资本融合在一起而形成的一种垄断资本。<span style=\"background-color: #f8cac6; color: #000000;\">银行垄断资本和工业垄断资本能够密切地融合</span>在一起，是<strong>通过</strong>()</p>\n<p>A.金融联系&radic;</p>\n<p>B.资本参与&radic;</p>\n<p>C.人事参与&radic;</p>\n<p>D.金融创新 <span style=\"background-color: #f8cac6; color: #000000;\">金融自由化与金融创新是金融垄断资本得以形成和壮大的重要制度条件</span></p>\n<p>【答案】ABC<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">银行垄断资本和工业垄断资本能够密切地融合在一起，是通过金融联系、资本参与、人事参与。口诀记忆为&ldquo;融资联系参与人&rdquo;。</span></p>","k":"考点78 资本主义从自由竞争到垄断","kid":"141","r":16264,"tot":24042},{"i":"144309","t":"多选","q":"金融寡头是指操纵国民经济命脉，并在实际上控制国家政权的少数垄断资本家或垄断资本家集团。他们支配了大量的社会财富，控制了整个国家的经济命脉和上层建筑，是垄断资本主义国家事实上的统治者。金融寡头对国家机器的控制，主要是通过同政府的“个人联合”来实现的，这种联合的途径包括()","o":{"A":"A.通过掌握一定数量的股票来层层控制企业的制度","B":"B.收买政府高官或国会议员","C":"C.聘请曾在政府任职的高官到公司担任高级职务","D":"D.直接把自己的代理人送进政府或议会"},"a":"BCD","j":"<p>金融寡头是指操纵国民经济命脉，并在实际上控制国家政权的少数垄断资本家或垄断资本家集团。他们支配了大量的社会财富，控制了整个国家的经济命脉和上层建筑，是垄断资本主义国家事实上的统治者。<span style=\"color: #e03e2d;\">|</span><span style=\"background-color: #f8cac6; color: #000000;\">金融寡头</span>对<span style=\"background-color: #f8cac6; color: #000000;\">国家机器的控制</span>，主要是通过同<span style=\"background-color: #f8cac6; color: #000000;\">政府的&ldquo;个人联合&rdquo;</span>来实现的，这种<strong>联合的途径包括</strong>()</p>\n<p>A.通过掌握一定数量的股票来层层控制企业的制度 <span style=\"background-color: #f8cac6; color: #000000;\">这是金融寡头在经济领域中的统治，即&ldquo;参与制&rdquo;</span></p>\n<p>B.收买政府高官或国会议员&radic;</p>\n<p>C.聘请曾在政府任职的高官到公司担任高级职务&radic;</p>\n<p>D.直接把自己的代理人送进政府或议会&radic;</p>\n<p>【答案】BCD<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">这种联合的途径包括收买政府高官或国会议员，聘请曾在政府任职的高官到公司担任高级职务，直接把自己的代理人送进政府或议会。</span></p>","k":"考点78 资本主义从自由竞争到垄断","kid":"141","r":10079,"tot":25169},{"i":"144310","t":"多选","q":"垄断资本的实质在于获取垄断利润，垄断利润是垄断资本家凭借其在社会生产和流通中的垄断地位而获得的超过平均利润的高额利润。垄断资本所获得的高额利润，归根到底来自无产阶级和其他劳动人民所创造的剩余价值。具体来说，垄断利润的来源主要有()","o":{"A":"A.剥削本国无产阶级和其他劳动人民","B":"B.非垄断企业的利润","C":"C.劳动人民创造的国民收入","D":"D.剥削和掠夺其他国家劳动人民"},"a":"ABCD","j":"<p>垄断资本的实质在于获取垄断利润，垄断利润是垄断资本家凭借其在社会生产和流通中的垄断地位而获得的超过平均利润的高额利润。垄断资本所获得的高额利润，归根到底来自无产阶级和其他劳动人民所创造的剩余价值。<span style=\"color: #e03e2d;\">|</span><span style=\"background-color: #f8cac6; color: #000000;\">具体来说，垄断利润的来源</span><strong>主要有</strong>()</p>\n<p>A.剥削本国无产阶级和其他劳动人民&radic;</p>\n<p>B.非垄断企业的利润&radic;</p>\n<p>C.劳动人民创造的国民收入&radic;</p>\n<p>D.剥削和掠夺其他国家劳动人民&radic;</p>\n<p>【答案】ABCD<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">垄断利润的来源主要有剥削本国无产阶级和其他劳动人民，非垄断企业的利润，劳动人民创造的国民收入，剥削和掠夺其他国家劳动人民。</span></p>","k":"考点78 资本主义从自由竞争到垄断","kid":"141","r":12364,"tot":24640},{"i":"144311","t":"多选","q":"第二次世界大战后，在所有发达资本主义国家，国家垄断资本主义无论在广度上还是深度上都有了更迅速、更普遍的发展，国家干预深入资本主义的生产、流通、分配和消费的各个环节，国家垄断资本主义作为一种新的垄断资本主义生产关系体系最终得以确立。国家垄断资本主义的形成和发展不是偶然的，其原因有()","o":{"A":"A.经济波动和经济危机的深化","B":"B.社会生产力的发展","C":"C.金融自由化与金融创新","D":"D.缓和社会矛盾、协调利益关系的需求"},"a":"ABD","j":"<p>第二次世界大战后，在所有发达资本主义国家，国家垄断资本主义无论在广度上还是深度上都有了更迅速、更普遍的发展，国家干预深入资本主义的生产、流通、分配和消费的各个环节，国家垄断资本主义作为一种新的垄断资本主义生产关系体系最终得以确立。<span style=\"color: #e03e2d;\">|</span><span style=\"background-color: #f8cac6; color: #000000;\">国家垄断资本主义的形成和发展</span>不是偶然的，<strong>其原因有</strong>()</p>\n<p>A.经济波动和经济危机的深化&radic;</p>\n<p>B.社会生产力的发展&radic;</p>\n<p>C.金融自由化与金融创新 <span style=\"background-color: #f8cac6; color: #000000;\">是金融垄断资本得以形成和壮大的重要制度条件，不合题意</span></p>\n<p>D.缓和社会矛盾、协调利益关系的需求&radic;</p>\n<p>【答案】ABD<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">国家垄断资本主义的形成和发展的原因有经济波动和经济危机的深化，社会生产力的发展，缓和社会矛盾、协调利益关系的需求。</span></p>","k":"考点79 国家垄断资本主义的形成及作用","kid":"142","r":10229,"tot":25540},{"i":"144312","t":"多选","q":"19世纪末20世纪初，自由竞争的资本主义转变为垄断资本主义的时候，国家垄断资本主义开始萌芽。第一次世界大战及其后的特大经济危机，使国家垄断资本主义在帝国主义各国普遍发展起来。第二次世界大战后，由于资本主义的基本矛盾日益深化，国家垄断资本主义迅速发展，成为当代帝国主义经济生活中的支配力量。国家垄断资本主义的主要形式有()","o":{"A":"A.宏观调节和微观规制","B":"B.国家所有并直接经营企业","C":"C.国家与私人共有、合营企业","D":"D.国家通过多种形式参与私人垄断资本的再生产过程"},"a":"ABCD","j":"<p>19世纪末20世纪初，自由竞争的资本主义转变为垄断资本主义的时候，国家垄断资本主义开始萌芽。第一次世界大战及其后的特大经济危机，使国家垄断资本主义在帝国主义各国普遍发展起来。第二次世界大战后，由于资本主义的基本矛盾日益深化，国家垄断资本主义迅速发展，成为当代帝国主义经济生活中的支配力量。<span style=\"background-color: #f8cac6; color: #000000;\">国家垄断资本主义的主要形式</span><strong>有</strong>()</p>\n<p>A.宏观调节和微观规制&radic;</p>\n<p>B.国家所有并直接经营企业&radic;</p>\n<p>C.国家与私人共有、合营企业&radic;</p>\n<p>D.国家通过多种形式参与私人垄断资本的再生产过程&radic;</p>\n<p>【答案】ABCD<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">国家垄断资本主义的主要形式有宏观调节和微观规制，国家所有并直接经营企业&middot;国家与私人共有、合营企业，国家通过多种形式参与私人垄断资本的再生产过程。</span></p>","k":"考点79 国家垄断资本主义的形成及作用","kid":"142","r":12201,"tot":24772},{"i":"144313","t":"多选","q":"第二次世界大战后，在美国的主导下建立了国际货币体系，即布雷顿森林体系，该体系对促进世界经济的恢复和发展发挥了重要作用，但也维护了美国的世界经济霸权地位。20世纪70年代初，由于资本主义发展不平衡的加深和国际货币体系内在矛盾的激化，布雷顿森林体系崩溃。随后，西方国家普遍走上金融自由化和金融创新的道路。金融自由化和金融创新推动资本主义经济的金融化程度不断提高，表现在()","o":{"A":"A.金融寡头发生分化，金融垄断资本脱离实体经济独立发展","B":"B.垄断资本主义的金融化程度不断提高","C":"C.金融业在国民经济中的地位大幅上升","D":"D.制造业就业人数严重减少，虚拟经济越来越脱离实体经济"},"a":"ABCD","j":"<p>第二次世界大战后，在美国的主导下建立了国际货币体系，即布雷顿森林体系，该体系对促进世界经济的恢复和发展发挥了重要作用，但也维护了美国的世界经济霸权地位。20世纪70年代初，由于资本主义发展不平衡的加深和国际货币体系内在矛盾的激化，布雷顿森林体系崩溃。随后，西方国家普遍走上金融自由化和金融创新的道路。<span style=\"background-color: #f8cac6; color: #000000;\">金融自由化和金融创新推动资本主义经济的金融化程度不断提高</span>，<strong>表现在</strong>()</p>\n<p>A.金融寡头发生分化，金融垄断资本脱离实体经济独立发展&radic;</p>\n<p>B.垄断资本主义的金融化程度不断提高&radic;</p>\n<p>C.金融业在国民经济中的地位大幅上升&radic;</p>\n<p>D.制造业就业人数严重减少，虚拟经济越来越脱离实体经济&radic;</p>\n<p>【答案】ABCD<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">金融自由化和金融创新推动资本主义经济的金融化程度不断提高，表现在金融寡头发生分化，金融垄断资本脱离实体经济独立发展；垄断资本主义的金融化程度不断提高；金融业在国民经济中的地位大幅上升；制造业就业人数严重减少，虚拟经济越来越脱离实体经济。</span></p>","k":"考点81 金融垄断资本的发展","kid":"146","r":13018,"tot":24137},{"i":"144314","t":"多选","q":"垄断资本在国内建立了垄断统治后，必然要把其统治势力扩展到国外，建立国际垄断统治。垄断资本向世界范围扩展的经济动因主要有()","o":{"A":"A.确保原材料和能源的可靠来源","B":"B.争夺商品销售市场","C":"C.加快技术向国外转移，以利于全世界共享","D":"D.将国内过剩的资本输出，以在别国谋求高额利润"},"a":"ABD","j":"<p>垄断资本在国内建立了垄断统治后，必然要把其统治势力扩展到国外，建立国际垄断统治。<span style=\"color: #e03e2d;\">|</span><span style=\"background-color: #f8cac6; color: #000000;\">垄断资本向世界范围扩展的经济动因</span><strong>主要有</strong>()</p>\n<p>A.确保原材料和能源的可靠来源&radic;</p>\n<p>B.争夺商品销售市场&radic;</p>\n<p>C.加快<strong>技术向国外转移</strong>，以利于全世界<strong>共享 </strong><span style=\"background-color: #f8cac6; color: #000000;\">应该是将部分非要害的技术转移到国外，以取得在别国的垄断优势，攫取高额垄断利润</span></p>\n<p>D.将国内<strong>过剩的</strong>资本输出，以在别国谋求高额利润&radic;</p>\n<p>【答案】ABD<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"background-color: #f8cac6; color: #000000;\">垄断资本向世界范围扩展的经济动因主要有确保原材料和能源的可靠来源；争夺商品销售市场；将国内过剩的资本输出，以在别国谋求高额利润。</span></p>","k":"考点80 垄断资本向世界范围扩展","kid":"144","r":17981,"tot":22888},{"i":"144315","t":"多选","q":"为了加强对各国垄断资本的协调和制约，防止彼此之间的激烈竞争可能引起的剧烈经济动荡，特别是防止发生全球性经济危机，在协商和合作的基础上，国际垄断资本还建立起国际经济调节体系，以加强国际协调。第二次世界大战以来，从事国际经济协调、维护国际经济秩序的国际性协调组织主要有()","o":{"A":"A.国际货币基金组织","B":"B.世界银行","C":"C.世界贸易组织","D":"D.国际劳工组织"},"a":"ABC","j":"<p>为了加强对各国垄断资本的协调和制约，防止彼此之间的激烈竞争可能引起的剧烈经济动荡，特别是防止发生全球性经济危机，在协商和合作的基础上，国际垄断资本还建立起国际经济调节体系，以加强国际协调。<span style=\"color: #e03e2d;\">|</span>第二次世界大战以来，<span style=\"background-color: #f8cac6; color: #000000;\">从事国际经济协调、维护国际经济秩序的国际性协调组织</span><strong>主要有</strong>()</p>\n<p>A.国际货币基金组织&radic;</p>\n<p>B.世界银行&radic;</p>\n<p>C.世界贸易组织&radic;</p>\n<p>D.国际劳工组织 <span style=\"background-color: #f8cac6; color: #000000;\">不合题意</span></p>\n<p>【答案】ABC<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">第二次世界大战以来，从事国际经济协调、维护国际经济秩序的国际性协调组织主要有国际货币基金组织，世界银行，世界贸易组织。</span></p>","k":"考点82 垄断资本国际化条件的垄断组织","kid":"149","r":16669,"tot":23003},{"i":"144316","t":"多选","q":"习近平总书记指出，经济全球化是不可逆转的历史大势；经济全球化是社会生产力发展的客观要求和科技进步的必然结果，不是哪些人、哪些国家人为造出来的。我们支持经济全球化，符合我国战略利益，顺应世界发展潮流。导致经济全球化迅猛发展的因素有()","o":{"A":"A.科学技术的进步和生产力的发展","B":"B.跨国公司的发展","C":"C.各国经济体制的变革","D":"D.国际经济组织的发展"},"a":"ABCD","j":"<p>习近平总书记指出，经济全球化是不可逆转的历史大势；经济全球化是社会生产力发展的客观要求和科技进步的必然结果，不是哪些人、哪些国家人为造出来的。我们支持经济全球化，符合我国战略利益，顺应世界发展潮流。<span style=\"color: #e03e2d;\">|</span><strong>导致经济全球化迅猛发展的因素有</strong>()</p>\n<p>A.科学技术的进步和生产力的发展&radic;</p>\n<p>B.跨国公司的发展&radic;</p>\n<p>C.各国经济体制的变革&radic;</p>\n<p>D.国际经济组织的发展&radic;</p>\n<p>【答案】ABCD<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">科学技术的进步和生产力的发展为经济全球化提供了坚实的物质基础和根本的推动力；跨国公司的发展为经济全球化提供了适宜的企业组织形式；各国经济体制的变革为经济全球化提供了体制保障；国际经济组织的发展为经济全球化提供了组织保障。</span></p>","k":"考点84 经济全球化及其影响","kid":"151","r":18387,"tot":22807},{"i":"144317","t":"多选","q":"第二次世界大战后，资本主义发生变化是客观事实，深刻分析这些变化的实质，有利于我们正确认识资本主义的本质，把握资本主义发展的趋势。第二次世界大战后资本主义发生变化的实质是()","o":{"A":"A.人类社会发展一般规律和资本主义经济规律作用的结果","B":"B.资本主义生产方式为适应生产力发展要求而作出自我调节的结果","C":"C.在资本主义制度基本框架内的变化","D":"D.一定程度上克服了资本主义的基本矛盾"},"a":"ABC","j":"<p>第二次世界大战后，资本主义发生变化是客观事实，深刻分析这些变化的实质，有利于我们正确认识资本主义的本质，把握资本主义发展的趋势。<span style=\"color: #e03e2d;\">Ⅱ</span><span style=\"background-color: #f8cac6; color: #000000;\">第二次世界大战后资本主义发生变化</span>的<strong>实质是</strong>()</p>\n<p>A.人类社会发展一般规律和资本主义经济规律作用的结果&radic;</p>\n<p>B.资本主义生产方式为适应生产力发展要求而作出自我调节的结果&radic;</p>\n<p>C.在资本主义制度基本框架内的变化&radic;</p>\n<p>D.一定程度上<strong>克服了</strong>资本主义的基本矛盾 <span style=\"background-color: #f8cac6; color: #000000;\">这些变化并没有改变资本主义制度的本质，并没有克服资本主义的基本矛盾，也没有改变马克思主义关于资本主义的基本论断的科学性</span></p>\n<p>【答案】ABC<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">第二次世界大战后资本主义发生变化的实质是人类社会发展一般规律和资本主义经济规律作用的结果，注意这是从根本上说，单选可考；资本主义生产方式为适应生产力发展要求而作出自我调节的结果，所以没有改变资本主义制度的本质；在资本主义制度基本框架内的变化，但并不意味着资本主义生产关系的根本性质发生了变化。</span></p>","k":"考点86 第二次世界大战后资本主义变化的原因和实质","kid":"155","r":17340,"tot":23003},{"i":"144318","t":"多选","q":"资本主义生产方式新变化在有效降低信息获取、资源匹配和商品交换成本，有力推动物质财富的创造和积累的同时，也推动资本积累方式从一般产业资本积累向国际金融垄断资本积累转变。国际金融资本的垄断成为当代资本主义最突出、最鲜明、最主要的特征。国际金融垄断资本的主要形式有()","o":{"A":"A.金融垄断寡头化","B":"B.金融垄断国际化","C":"C.产业实体化","D":"D.经济虚拟化"},"a":"ABD","j":"<p>资本主义生产方式新变化在有效降低信息获取、资源匹配和商品交换成本，有力推动物质财富的创造和积累的同时，也推动资本积累方式从一般产业资本积累向国际金融垄断资本积累转变。国际金融资本的垄断成为<span style=\"background-color: #f8cac6; color: #000000;\">当代资本主义最突出、最鲜明、最主要的特征</span>。<span style=\"color: #e03e2d;\">||</span><span style=\"background-color: #f8cac6; color: #000000;\">国际金融垄断资本</span>的<strong>主要形式有</strong>()</p>\n<p>A.金融垄断寡头化&radic;</p>\n<p>B.金融垄断国际化&radic;</p>\n<p>C.产业<strong>实体化 </strong><span style=\"background-color: #f8cac6; color: #000000;\">应该是&ldquo;产业空心化&rdquo;</span></p>\n<p>D.经济虚拟化&radic;</p>\n<p>【答案】ABD<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">国际金融垄断资本的主要形式有金融垄断寡头化，金融垄断国际化，经济虚拟化、产业空心化。</span></p>","k":"考点87 当代资本主义变化的新特征","kid":"156","r":12753,"tot":23970},{"i":"144319","t":"多选","q":"在2008年危机的影响下，西方国家的经济生活、政治生活和社会民生等方面都出现了各种问题。资本主义社会问题加速积累，资本主义国家内部的矛盾和冲突日益明显。这些矛盾和冲突表现为()","o":{"A":"A.经济发展失调","B":"B.政治体制失灵","C":"C.社会融合机制失效","D":"D.文化多元机制失衡"},"a":"ABC","j":"<p>在2008年危机的影响下，西方国家的经济生活、政治生活和社会民生等方面都出现了各种问题。资本主义社会问题加速积累，资本主义国家内部的矛盾和冲突日益明显。<span style=\"color: #e03e2d;\">|</span><strong>这些矛盾和冲突表现为</strong>()</p>\n<p>A.经济发展失调&radic;</p>\n<p>B.政治体制失灵&radic;</p>\n<p>C.社会融合机制失效&radic;</p>\n<p>D.文化多元机制失衡 <span style=\"background-color: #f8cac6; color: #000000;\">无此表现</span></p>\n<p>【答案】ABC<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">这些矛盾和冲突表现为经济发展失调，政治体制失灵，社会融合机制失效。</span></p>","k":"考点88 世界大变局下资本主义的矛盾与冲突","kid":"718","r":11975,"tot":24062},{"i":"144320","t":"多选","q":"习近平总书记明确指出：“事实一再告诉我们，马克思、恩格斯关于资本主义社会基本矛盾的分析没有过时，关于资本主义必然消亡、社会主义必然胜利的历史唯物主义观点也没有过时。这是社会历史发展不可逆转的总趋势，资本主义最终消亡，社会主义最终胜利。”资本主义为社会主义所代替的历史必然性在于()","o":{"A":"A.资本主义基本矛盾“包含着现代的一切冲突的萌芽”","B":"B.国家垄断资本主义将成为社会主义的前奏","C":"C.资本主义社会存在着两大阶级之间的斗争和矛盾","D":"D.资本积累推动资本主义基本矛盾激化并否定资本主义自身"},"a":"ABCD","j":"<p>习近平总书记明确指出：&ldquo;事实一再告诉我们，马克思、恩格斯关于资本主义社会基本矛盾的分析没有过时，关于资本主义必然消亡、社会主义必然胜利的历史唯物主义观点也没有过时。这是社会历史发展不可逆转的总趋势，资本主义最终消亡，社会主义最终胜利。&rdquo;<span style=\"color: #e03e2d;\">||</span><span style=\"background-color: #f8cac6; color: #000000;\">资本主义为社会主义所代替的历史必然性</span><strong>在于</strong>()</p>\n<p>A.资本主义基本矛盾&ldquo;包含着现代的一切冲突的萌芽&rdquo;&radic;</p>\n<p>B.国家垄断资本主义将成为社会主义的前奏&radic;</p>\n<p>C.资本主义社会存在着两大阶级之间的斗争和矛盾&radic;</p>\n<p>D.资本积累推动资本主义基本矛盾激化并否定资本主义自身&radic;</p>\n<p>【答案】ABCD<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">资本主义为社会主义所代替的历史必然性在于资本主义基本矛盾&ldquo;包含着现代的一切冲突的萌芽&rdquo;,国家垄断资本主义将成为社会主义的前奏，资本主义社会存在着两大阶级之间的斗争和矛盾，资本积累推动资本主义基本矛盾激化并否定资本主义自身。</span></p>","k":"考点89 资本主义的历史地位","kid":"719","r":12624,"tot":23920},{"i":"144321","t":"单选","q":"二战后，西方国家曾普遍推行“从摇篮到坟墓”的社会福利。但在2026年的经济环境中，这些国家纷纷转向强调“个人竞争”和“市场效率”。这一转变表明()","o":{"A":"A.资本主义国家的职能已经由阶级统治转向了纯粹的社会管理","B":"B.国家干预经济的形式会根据资本积累的现实需要进行灵活调整","C":"C.资产阶级政府已经完全丧失了调节社会矛盾的政治控制能力","D":"D.自由放任的市场竞争是资本主义社会形态保持活力的唯一出路"},"a":"B","j":"<p>二战后，西方国家曾普遍推行&ldquo;从摇篮到坟墓&rdquo;的社会福利。但在2026年的经济环境中，这些国家纷纷转向强调&ldquo;个人竞争&rdquo;和&ldquo;市场效率&rdquo;。<span style=\"color: #e03e2d;\">|</span><span style=\"background-color: #f8cac6; color: #000000;\">这一转变</span><strong>表明</strong>()</p>\n<p>A.资本主义国家的职能已经由阶级统治转向了<strong>纯粹的社会管理</strong> <span style=\"background-color: #f8cac6; color: #000000;\">绝对表述错误</span></p>\n<p>B.国家干预经济的形式会根据资本积累的现实需要进行灵活调整&radic;</p>\n<p>C.资产阶级政府<strong>已经完全丧失了</strong>调节社会矛盾的政治控制能力 <span style=\"background-color: #f8cac6; color: #000000;\">绝对表述错误</span></p>\n<p>D.自由放任的市场竞争是资本主义社会形态保持活力<strong>的唯一出路</strong> <span style=\"background-color: #f8cac6; color: #000000;\">绝对表述错误</span></p>\n<p>【答案】B<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">国家干预的形式是为维护统治服务的，会随形势调整。</span></p>","k":"考点72 资本积累★★","kid":"712","r":18827,"tot":23019},{"i":"144322","t":"单选","q":"在2026年的西方社会评论中，“消失的中间阶层”和“身份政治”成为高频词，揭示了民众对社会归属感的丧失。这反映了资本主义在当代()","o":{"A":"A.社会融合机制陷入深刻危机，难以消解多元矛盾","B":"B.金融垄断资本对实体经济的严重剥蚀和财富掠夺","C":"C.选举政治由于资本操控而沦为“金钱博弈”的本质","D":"D.通过文化输出在全球范围内输出意识形态的失败"},"a":"A","j":"<p>在2026年的西方社会评论中，&ldquo;消失的中间阶层&rdquo;和&ldquo;身份政治&rdquo;成为高频词，揭示了民众对<span style=\"background-color: #f8cac6; color: #000000;\">社会归属感</span>的丧失。<span style=\"color: #e03e2d;\">|</span><strong>这反映了</strong><span style=\"background-color: #f8cac6; color: #000000;\">资本主义在当代</span>()</p>\n<p>A.社会融合机制陷入深刻危机，难以消解多元矛盾&radic;</p>\n<p>B.金融垄断资本对<strong>实体经济</strong>的严重剥蚀和财富掠夺</p>\n<p>C.<strong>选举政治</strong>由于资本操控而沦为&ldquo;金钱博弈&rdquo;的本质</p>\n<p>D.通过<strong>文化输出</strong>在全球范围内输出意识形态的失败 <span style=\"background-color: #f8cac6; color: #000000;\">BCD不合题意</span></p>\n<p>【答案】A<span style=\"background-color: #f8cac6; color: #000000;\">材料思考题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">&ldquo;消失的中间阶层&rdquo;和&ldquo;身份政治&rdquo;,以及&ldquo;社会归属感&rdquo;,都反映了资本主义社会融合机制失效的弊端。</span></p>","k":"考点88 世界大变局下资本主义的矛盾与冲突","kid":"718","r":14904,"tot":23710},{"i":"144323","t":"单选","q":"垄断组织通过制定垄断价格来获取垄断利润。在市场交易过程中，垄断组织获利高低实际上受到很多因素的影响。为了避免遭受净亏损，垄断组织所能接受的最低价格是()","o":{"A":"A.成本价格","B":"B.生产价格","C":"C.垄断低价","D":"D.垄断高价"},"a":"A","j":"<p>垄断组织通过制定垄断价格来获取垄断利润。在市场交易过程中，垄断组织获利高低实际上受到很多因素的影响。<span style=\"background-color: #f8cac6; color: #000000;\">为了避免遭受净亏损</span>，<strong>垄断组织</strong>所能接受的<strong>最低价格</strong>是()</p>\n<p>A.成本价格&radic;</p>\n<p>B.生产价格 <span style=\"background-color: #f8cac6; color: #000000;\">生产价格=成本价格+平均利润，有平均利润说明处于盈利的状态，不符合&ldquo;最低价格&rdquo;,不合题意</span></p>\n<p>C.垄断低价 <span style=\"background-color: #f8cac6; color: #000000;\">CD这是垄断价格的两种形式，即垄断性企业采取&ldquo;低价买入&rdquo;&ldquo;高价卖出&rdquo;的方式，但都不是为避免净亏损能接受的最低价格</span></p>\n<p>D.垄断高价</p>\n<p>【答案】A<span style=\"color: #000000;\">材<span style=\"background-color: #f8cac6;\">料思考题</span></span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">垄断价格=成本价格+平均利润+垄断利润。所谓最低价格即为去掉一切利润后的价格，即成本价格。</span></p>","k":"考点78 资本主义从自由竞争到垄断","kid":"141","r":8841,"tot":25102},{"i":"144324","t":"单选","q":"在资本主义条件下，某汽车垄断企业在一个生产周期内耗费的生产资料价值为200万元，支付给工人的工资为100万元。此时，汽车行业的平均利润率为20%,该企业在这一周期获得的利润为240万元。在这一生产周期内，如果生产100辆汽车，则每辆汽车的销售价格为()","o":{"A":"A.3万元","B":"B.4万元","C":"C.5万元","D":"D.6万元"},"a":"D","j":"<p>在资本主义条件下，某汽车垄断企业在一个生产周期内耗费的生产资料价值为200万元，支付给工人的工资为100万元。此时，汽车行业的平均利润率为20%,该企业在这一周期获得的利润为240万元。<span style=\"color: #e03e2d;\">|</span>在这一生产周期内，如果生产100辆汽车，则<span style=\"background-color: #f8cac6; color: #000000;\">每辆汽车的销售价格</span><strong>为</strong>()</p>\n<p>A.3万元</p>\n<p>B.4万元</p>\n<p>C.5万元</p>\n<p>D.6万元&radic;</p>\n<p>【答案】D<span style=\"background-color: #f8cac6; color: #000000;\">材料思考题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">生产成本为：不变资本200万元+可变资本100万元=300万元；平均利润为：生产成本300万元&times;平均利润率20%=60万元。根据公式：垄断价格=成本+平均利润+垄断利润，垄断价格=300万元+60万元+240万元=600万元。生产了100辆汽车，600万元/100=6万元。</span></p>","k":"考点78 资本主义从自由竞争到垄断","kid":"141","r":11131,"tot":23897},{"i":"144325","t":"单选","q":"20世纪70年代以来，西方资本主义国家的金融资本急剧膨胀，这一方面促进了资本主义的发展，另一方面也造成了经济过度虚拟化，致使金融危机频繁发生。西方资本主义金融资本快速发展壮大的重要制度条件是()","o":{"A":"A.金融自由化与金融创新","B":"B.技术创新与大力发展互联网金融","C":"C.全面私有化与放松金融监管","D":"D.去工业化与大力发展现代服务业"},"a":"A","j":"<p>20世纪70年代以来，西方资本主义国家的金融资本急剧膨胀，这一方面促进了资本主义的发展，另一方面也造成了经济过度虚拟化，致使金融危机频繁发生。<span style=\"color: #e03e2d;\">|</span>西方资本主义<span style=\"background-color: #f8cac6; color: #000000;\">金融资本快速发展壮大的重要制度条件</span><strong>是</strong>()</p>\n<p>A.金融自由化与金融创新&radic;</p>\n<p>B.技术创新与大力发展互联网金融 <span style=\"background-color: #f8cac6; color: #000000;\">金融垄断资本发展的表现</span></p>\n<p>C.<strong>全面私有化</strong>与<strong>放松</strong>金融监管 <span style=\"background-color: #f8cac6; color: #000000;\">基础知识错误</span></p>\n<p>D.去工业化与大力发展现代服务业 <span style=\"background-color: #f8cac6; color: #000000;\">金融垄断资本发展的表现</span></p>\n<p>【答案】A<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">西方资本主义金融资本快速发展壮大的重要制度条件是金融自由化与金融创新。</span></p>","k":"考点81 金融垄断资本的发展","kid":"146","r":16999,"tot":23067},{"i":"144326","t":"单选","q":"习近平总书记在亚太经合组织工商领导人峰会上的书面演讲中提出，“我们要正确引导经济全球化方向，不能走少数国家独占霸权的老路。我们要推动经济全球化更多释放正面效应，进入更有活力、更加包容、更可持续的新阶段”。为经济全球化发展提供了坚实的物质基础和根本的推动力的是()","o":{"A":"A.跨国公司的发展","B":"B.各国经济体制的变革和国际组织的发展","C":"C.商品和劳务在全球范围内自由流动","D":"D.科学技术的进步和生产力的发展"},"a":"D","j":"<p>习近平总书记在亚太经合组织工商领导人峰会上的书面演讲中提出，&ldquo;我们要正确引导经济全球化方向，不能走少数国家独占霸权的老路。我们要推动经济全球化更多释放正面效应，进入更有活力、更加包容、更可持续的新阶段&rdquo;。<span style=\"color: #e03e2d;\">|</span><span style=\"background-color: #f8cac6; color: #000000;\">为经济全球化发展提供了坚实的物质基础和根本的推动力</span>的<strong>是</strong>()</p>\n<p>A.跨国公司的发展 <span style=\"background-color: #f8cac6; color: #000000;\">跨国公司的发展为经济全球化提供了适宜的企业组织形式</span></p>\n<p>B.各国经济体制的变革和国际组织的发展 <span style=\"background-color: #f8cac6; color: #000000;\">各国经济体制的变革和国际经济组织的发展是经济全球化的体制与组织保障</span></p>\n<p>C.商品和劳务在全球范围内自由流动 <span style=\"background-color: #f8cac6; color: #000000;\">这是经济全球化的表现之一贸易全球化，不合题意</span></p>\n<p>D.科学技术的进步和生产力的发展&radic;</p>\n<p>【答案】D<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">为经济全球化发展提供了坚实的物质基础和根本的推动力的是科学技术的进步和生产力的发展。</span></p>","k":"考点84 经济全球化及其影响","kid":"151","r":18136,"tot":22749},{"i":"144327","t":"单选","q":"从历史发展的角度看，资本主义生产资料所有制是不断演进和变化的。第二次世界大战后，资本主义所有制发生了新的变化。当今资本主义社会具有主导地位的资本所有制形式是()","o":{"A":"A.私人资本所有制","B":"B.法人资本所有制","C":"C.私人股份资本所有制","D":"D.垄断资本私人所有制"},"a":"B","j":"<p>从历史发展的角度看，资本主义生产资料所有制是不断演进和变化的。<span style=\"background-color: #f8cac6; color: #000000;\">第二次世界大战后，</span>资本主义所有制发生了新的变化。<span style=\"color: #e03e2d;\">|</span><span style=\"background-color: #f8cac6; color: #000000;\">当今资本主义社会具有主导地位的资本所有制形式</span><strong>是</strong>()</p>\n<p>A.私人资本所有制 <span style=\"background-color: #f8cac6; color: #000000;\">资本主义发展初期占主导地位的所有制形式，不符合&ldquo;二战后&rdquo;</span></p>\n<p>B.法人资本所有制&radic;</p>\n<p>C.私人股份资本所有制 <span style=\"background-color: #f8cac6; color: #000000;\">19世纪末20世纪初占主导地位的所有制形式，不符合&ldquo;二战后&rdquo;</span></p>\n<p>D.垄断资本私人所有制 <span style=\"background-color: #f8cac6; color: #000000;\">无此表述</span></p>\n<p>【答案】B<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">当今资本主义社会具有主导地位的资本所有制形式是法人资本所有制。</span></p>","k":"考点85 第二次世界大战后资本主义变化的主要表现","kid":"153","r":13088,"tot":23691},{"i":"144328","t":"单选","q":"与第二次世界大战前的资本主义相比，当代资本主义在许多方面已经并正在发生着深刻的变化。当代资本主义社会，大公司经营活动的实际控制者是()","o":{"A":"A.高级职业经理","B":"B.股东大会","C":"C.监事会","D":"D.董事长"},"a":"A","j":"<p>与<span style=\"background-color: #f8cac6; color: #000000;\">第二次世界大战</span>前的资本主义相比，当代资本主义在许多方面已经并正在发生着深刻的变化。<span style=\"color: #e03e2d;\">I</span>当代资本主义社会，<span style=\"background-color: #f8cac6; color: #000000;\">大公司经营活动的实际控制者</span><strong>是</strong>()</p>\n<p>A.高级职业经理&radic;</p>\n<p>B.股东大会 <span style=\"background-color: #f8cac6; color: #000000;\">不合题意</span></p>\n<p>C.监事会<span style=\"color: #000000;\"> <span style=\"background-color: #f8cac6;\">不合题意</span></span></p>\n<p>D.董事长 <span style=\"background-color: #f8cac6; color: #000000;\">不合题意</span></p>\n<p>【答案】A<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">当代资本主义社会，大公司经营活动的实际控制者是高级职业经理，这是第二次世界大战后资本主义新变化中的社会阶层和社会结构变化。具体表现为，第一，资本家的地位和作用已经发生很大变化。第二，高级职业经理成为大公司经营活动的实际控制者。第三，知识型和服务型劳动者的数量不断增加，劳动方式发生了新变化。</span></p>","k":"考点85 第二次世界大战后资本主义变化的主要表现","kid":"153","r":13960,"tot":23443},{"i":"144329","t":"单选","q":"在当代资本主义生产关系中，社会阶层、阶级结构发生了新的变化。随着工业中现代化、自动化服务和新工艺的广泛采用，新的生产管理方法和生产组织形式的广泛实行，从事体力劳动的蓝领工人越来越少，从事脑力劳动的白领工人不断增加。知识型和服务型劳动者的数量不断增加，说明劳动方式发生的新变化是()","o":{"A":"A.实现了从传统劳动方式向现代劳动方式的转变","B":"B.实现了劳动者生活状况、工资水平的提高","C":"C.职工参与决策、终身雇佣、职工持股","D":"D.实施了普及化、全民化的社会福利制度"},"a":"A","j":"<p>在当代资本主义生产关系中，社会阶层、阶级结构发生了新的变化。随着工业中现代化、自动化服务和新工艺的广泛采用，新的生产管理方法和生产组织形式的广泛实行，从事体力劳动的蓝领工人越来越少，从事脑力劳动的白领工人不断增加。|知识型和服务型劳动者的数量不断增加，<strong>说明</strong><span style=\"background-color: #f8cac6; color: #000000;\">劳动方式发生的新变化</span>是()</p>\n<p>A.实现了从传统劳动方式向现代劳动方式的转变&radic;</p>\n<p>B.实现了劳动者生活状况、工资水平的提高</p>\n<p>C.职工参与决策、终身雇佣、职工持股</p>\n<p>D.实施了普及化、全民化的社会福利制度 <span style=\"background-color: #f8cac6; color: #000000;\">BCD为第二次世界大战后，当代资本主义社会发生的劳资关系和分配关系的变化</span></p>\n<p>【答案】A<span style=\"background-color: #f8cac6; color: #000000;\">材料思考题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">知识型和服务型劳动者的数量不断增加，说明劳动方式发生的新变化是实现了从传统劳动方式向现代劳动方式的转变。</span></p>","k":"考点85 第二次世界大战后资本主义变化的主要表现","kid":"153","r":18493,"tot":22628},{"i":"144330","t":"单选","q":"在资本主义发展的初期，生产资料经济上的所有权与法律上的所有权是一致的，所有权与控制权统一于资本家自身。这一时期占主导地位的所有制形式是()","o":{"A":"A.法人资本所有制","B":"B.私人股份资本所有制","C":"C.资本主义生产资料私有制","D":"D.私人资本所有制"},"a":"D","j":"<p>在<span style=\"background-color: #f8cac6; color: #000000;\">资本主义发展的初期</span>，生产资料经济上的所有权与法律上的所有权是一致的，所有权与控制权统一于资本家自身。<span style=\"color: #e03e2d;\">|</span><span style=\"background-color: #f8cac6; color: #000000;\">这一时期</span>占<strong>主导地位的所有制形式是</strong>()</p>\n<p>A.法人资本所有制 <span style=\"background-color: #f8cac6; color: #000000;\">第二次世界大战后，法人资本所有制崛起并成为居主导地位的资本所有制形式</span></p>\n<p>B.私人股份资本所有制 <span style=\"background-color: #f8cac6; color: #000000;\">19世纪末20世纪初，私人股份资本所有制取代私人资本所有制成为占主导地位的所有制形式</span></p>\n<p>C.资本主义生产资料私有制 <span style=\"background-color: #f8cac6; color: #000000;\">是资本主义制度的经济基础</span></p>\n<p>D.私人资本所有制&radic;</p>\n<p>【答案】D<span style=\"color: #000000;\">判<span style=\"background-color: #f8cac6;\">断纯背题</span></span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">资本主义发展的初期占主导地位的所有制形式是私人资本所有制。</span></p>","k":"考点85 第二次世界大战后资本主义变化的主要表现","kid":"153","r":13028,"tot":24082},{"i":"144331","t":"单选","q":"正确认识第二次世界大战后资本主义变化的原因和实质，对于在新的历史条件下深刻把握资本主义的本质和规律，具有十分重要的意义。资本主义发生变化的根本推动力量是()","o":{"A":"A.工人阶级争取自身权利和利益的斗争","B":"B.社会主义制度初步显示的优越性","C":"C.科学技术革命和生产力的发展","D":"D.主张改良主义的政党对资本主义制度的改革"},"a":"C","j":"<p>正确认识<span style=\"background-color: #f8cac6; color: #000000;\">第二次世界大战后</span>资本主义变化的原因和实质，对于在新的历史条件下深刻把握资本主义的本质和规律，具有十分重要的意义。<span style=\"color: #e03e2d;\">|</span><span style=\"background-color: #f8cac6; color: #000000;\">资本主义发生变化</span>的<strong>根本推动力量是</strong>()</p>\n<p>A.工人阶级争取自身权利和利益的斗争</p>\n<p>B.社会主义制度初步显示的优越性</p>\n<p>C.科学技术革命和生产力的发展&radic;</p>\n<p>D.主张改良主义的政党对资本主义制度的改革<span style=\"color: #000000;\"> <span style=\"background-color: #f8cac6;\">ABD:为第二次世界大战后资本主义变化的其他原因，并非根本推动力量。</span></span></p>\n<p>【答案】C<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">资本主义发生变化的根本推动力量是科学技术革命和生产力的发展。</span></p>","k":"考点86 第二次世界大战后资本主义变化的原因和实质","kid":"155","r":19223,"tot":22403},{"i":"144332","t":"多选","q":"在2026年数字经济博览会上，专家指出，当今互联网平台的扩张并非简单的机器堆砌，而是通过算法专利的“资本聚集”实现的。生产集中和资本集中发展到一定阶段必然引起垄断，这是因为()","o":{"A":"A.少数大企业之间容易达成协议来操纵和控制市场","B":"B.少数大企业具有极大的破坏性，竞争成本极高","C":"C.企业规模巨大使得中小企业进入该行业的门槛极高","D":"D.垄断组织可以通过技术霸权彻底消除价值规律的作用"},"a":"ABC","j":"<p>在2026年数字经济博览会上，专家指出，当今互联网平台的扩张并非简单的机器堆砌，而是通过算法专利的&ldquo;资本聚集&rdquo;实现的。<span style=\"color: #e03e2d;\">Ⅱ</span>生产集中和资本集中发展到一定阶段<span style=\"background-color: #f8cac6;\"><span style=\"color: #000000;\">必然引起垄</span>断</span>，<strong>这是因为</strong>()</p>\n<p>A.少数大企业之间容易达成协议来操纵和控制市场&radic;</p>\n<p>B.少数大企业具有极大的破坏性，竞争成本极高&radic;</p>\n<p>C.企业规模巨大使得中小企业进人该行业的门槛极高&radic;</p>\n<p>D.垄断组织可以通过技术霸权<strong>彻底消除价值规律</strong>的作用 <span style=\"background-color: #f8cac6; color: #000000;\">垄断不能消除价值规律，只能改变其表现形式</span></p>\n<p>【答案】ABC<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">ABC分别从主观协议、客观避损和行业壁垒三个维度阐述了垄断的必然性。</span></p>","k":"考点78 资本主义从自由竞争到垄断","kid":"141","r":17699,"tot":21999},{"i":"144333","t":"多选","q":"某国际劳工组织报告分析称，尽管发达国家普遍存在“终身雇佣”和“利润分享”,但贫富差距仍在扩大。这说明这些制度()","o":{"A":"A.是资本主义生产关系在自身范围内进行的局部调整","B":"B.是为了更好地攫取剩余价值和提高劳动生产率","C":"C.并没有触动资本主义私有制这一矛盾的根源","D":"D.其作用的发挥受制于资本积累和获取利润的需要"},"a":"ABCD","j":"<p>某国际劳工组织报告分析称，尽管发达国家普遍存在<span style=\"background-color: #f8cac6; color: #000000;\">&ldquo;终身雇佣&rdquo;和&ldquo;利润分享&rdquo;</span>,但<span style=\"background-color: #f8cac6; color: #000000;\">贫富差距</span>仍在扩大。<strong>这说明</strong><span style=\"background-color: #f8cac6; color: #000000;\">这些制度</span>()</p>\n<p>A.是资本主义生产关系在自身范围内进行的局部调整&radic;</p>\n<p>B.是为了更好地攫取剩余价值和提高劳动生产率&radic;</p>\n<p>C.并没有触动资本主义私有制这一矛盾的根源&radic;</p>\n<p>D.其作用的发挥受制于资本积累和获取利润的需要&radic;</p>\n<p>【答案】ABCD<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">所谓&ldquo;终身雇佣&rdquo;和&ldquo;利润分享&rdquo;,只是当代资本主义国家为缓和劳资矛盾采取的激励制度，仍然不会改变资本主义的局限性。</span></p>","k":"考点87 当代资本主义变化的新特征","kid":"156","r":15021,"tot":22518},{"i":"144334","t":"多选","q":"当前，西方主要国家面临严重的通货膨胀与社会动荡并存的“复合危机”。审视21世纪资本主义的新变化，我们应当看到()","o":{"A":"A.生产社会化程度的提高与私有制的冲突依然存在","B":"B.金融化导致实体经济空心化，加剧了系统性风险","C":"C.科技进步带来的红利更多被少数垄断资本所侵占","D":"D.资本主义的制度框架已难以承载当代生产力的发展"},"a":"ABCD","j":"<p>当前，西方主要国家面临严重的通货膨胀与社会动荡并存的&ldquo;复合危机&rdquo;。<span style=\"color: #e03e2d;\">||</span><span style=\"background-color: #f8cac6; color: #000000;\">审视21世纪资本主义的新变化，我们应当</span><strong>看到</strong>()</p>\n<p>A.生产社会化程度的提高与私有制的冲突依然存在&radic;</p>\n<p>B.金融化导致实体经济空心化，加剧了系统性风险&radic;</p>\n<p>C.科技进步带来的红利更多被少数垄断资本所侵占&radic;</p>\n<p>D.资本主义的制度框架已难以承载当代生产力的发展&radic;</p>\n<p>【答案】ABCD<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">21世纪以来资本主义出现了一些新变化新特征，如金融垄断资本主义的影响力向全社会深度渗透等等。ABCD四项从矛盾、金融、分配和制度四个维度总结了21世纪资本主义新变化的负面后果与本质局限。</span></p>","k":"考点87 当代资本主义变化的新特征","kid":"156","r":16395,"tot":22248},{"i":"144335","t":"多选","q":"垄断利润主要是通过垄断组织制定的垄断价格来实现的。垄断价格是垄断组织在销售或购买商品时，凭借其垄断地位规定的、旨在保证获取最大限度利润的市场价格。垄断价格()","o":{"A":"A.完全脱离了生产价格和价值","B":"B.没有否定价值规律，是价值规律在垄断资本主义阶段作用的具体体现","C":"C.增加了整个社会所生产的价值总量","D":"D.不能创造价值和剩余价值"},"a":"BD","j":"<p>垄断利润主要是通过垄断组织制定的垄断价格来实现的。垄断价格是垄断组织在销售或购买商品时，凭借其垄断地位规定的、旨在保证获取最大限度利润的市场价格。<span style=\"background-color: #f8cac6; color: #000000;\">垄断价格</span>()</p>\n<p>A.<strong>完全脱离了</strong>生产价格和价值 <span style=\"background-color: #f8cac6; color: #000000;\">垄断价格一定时期内背离生产价格和价值，但不是完全脱离</span></p>\n<p>B.没有否定价值规律，是价值规律在垄断资本主义阶段作用的具体体现&radic;</p>\n<p>C.<strong>增加了</strong>整个社会所生产的价值总量 <span style=\"background-color: #f8cac6; color: #000000;\">垄断价格既不能增加也不能减少整个社会所生产的价值总量</span></p>\n<p>D.不能创造价值和剩余价值&radic;</p>\n<p>【答案】BD<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">垄断价格没有否定价值规律，是价值规律在垄断资本主义阶段作用的具体体现；不能创造价值和剩余价值，这是由雇佣工人创造的，垄断本身不能。</span></p>","k":"考点78 资本主义从自由竞争到垄断","kid":"141","r":12363,"tot":23270},{"i":"144336","t":"多选","q":"垄断资本的实质在于获取垄断利润。垄断利润主要是通过垄断组织制定的垄断价格来实现的。垄断价格包括垄断高价和垄断低价两种形式。垄断组织操纵价格带来的结果是()","o":{"A":"A.抑制了市场上价格的自由波动","B":"B.垄断价格一定时期内背离生产价格和价值","C":"C.整个社会商品的价值不再是由生产它们的社会必要劳动时间决定","D":"D.对商品价值和剩余价值作了有利于垄断资本的再分配"},"a":"ABD","j":"<p>垄断资本的实质在于获取垄断利润。垄断利润主要是通过垄断组织制定的垄断价格来实现的。垄断价格包括垄断高价和垄断低价两种形式。<span style=\"color: #e03e2d;\">||</span><span style=\"background-color: #f8cac6; color: #000000;\">垄断组织操纵价格</span>带来的<strong>结果是</strong>()</p>\n<p>A.抑制了市场上价格的自由波动&radic;</p>\n<p>B.垄断价格一定时期内背离生产价格和价值&radic;</p>\n<p>C.整个社会商品的价值<strong>不再是</strong>由生产它们的社会必要劳动时间决定 <span style=\"background-color: #f8cac6; color: #000000;\">基础知识错误，仍然是</span></p>\n<p>D.对商品价值和剩余价值作了有利于垄断资本的再分配&radic;</p>\n<p>【答案】ABD<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">垄断组织操纵价格带来的结果是抑制了市场上价格的自由波动，垄断价格一定时期内背离生产价格和价值，对商品价值和剩余价值作了有利于垄断资本的再分配。</span></p>","k":"考点78 资本主义从自由竞争到垄断","kid":"141","r":12467,"tot":22838},{"i":"144337","t":"多选","q":"垄断资本在国内建立了垄断统治后，必然要把其统治势力扩展到国外，建立国际垄断组织。垄断资本向世界范围扩展的基本形式有()","o":{"A":"A.借贷资本","B":"B.货币资本","C":"C.生产资本","D":"D.商品资本"},"a":"ACD","j":"<p>垄断资本在国内建立了垄断统治后，必然要把其统治势力扩展到国外，建立国际垄断组织。<span style=\"background-color: #f8cac6; color: #000000;\">垄断资本向世界范围扩展的基本形式</span><strong>有</strong>()</p>\n<p>A.借贷资本&radic;</p>\n<p>B.货币资本 <span style=\"background-color: #f8cac6; color: #000000;\">这是产业资本循环的职能</span></p>\n<p>C.生产资本&radic;</p>\n<p>D.商品资本&radic;</p>\n<p>【答案】ACD<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">垄断资本向世界范围扩展的基本形式有借贷资本，生产资本，商品资本。口诀记忆为&ldquo;产品借贷输出世界&rdquo;。</span></p>","k":"考点80 垄断资本向世界范围扩展","kid":"144","r":8276,"tot":24234},{"i":"144338","t":"多选","q":"当前经济全球化虽然面临不少阻力，但总体看，动力胜过阻力，各国走向开放、走向合作的大势没有改变、也不会改变。习近平总书记指出，“我们不能把经济全球化一棍子打死，而是要适应和引导好经济全球化，让它更好惠及每个国家、每个民族。”这表明()","o":{"A":"A.经济全球化可以带来巨大的分工利益，推动世界生产力的发展","B":"B.不仅发达国家从中受益，一些发展中国家在参与经济全球化进程中也得到了快速发展","C":"C.在经济全球化进程中，资金、技术等生产要素可以在国际社会流动和优化配置","D":"D.经济全球化造成了当今困扰世界的很多问题"},"a":"ABC","j":"<p><span style=\"background-color: #f8cac6; color: #000000;\">当前经济全球化</span>虽然面临不少阻力，但总体看，动力胜过阻力，各国走向开放、走向合作的<span style=\"background-color: #f8cac6; color: #000000;\">大势</span>没有改变、也不会改变。习近平总书记指出，&ldquo;我们不能把经济全球化一棍子打死，而是要<span style=\"background-color: #f8cac6; color: #000000;\">适应和引导好</span>经济全球化，让它更好惠及每个国家、每个民族。&rdquo;<span style=\"color: #e03e2d;\">||</span>这<strong>表明</strong>()</p>\n<p>A.经济全球化可以带来巨大的分工利益，推动世界生产力的发展&radic; <span style=\"background-color: #f8cac6; color: #000000;\">即经济全球化的&ldquo;大势&rdquo;</span></p>\n<p>B.不仅发达国家从中受益，一些发展中国家在参与经济全球化进程中也得到了快速发展&radic;</p>\n<p>C.在经济全球化进程中，资金、技术等生产要素可以在国际社会流动和优化配置&radic;</p>\n<p>D.经济全球化<strong>造成了</strong>当今困扰世界的很多问题 <span style=\"background-color: #f8cac6; color: #000000;\">当今困扰世界的很多问题并不是经济全球化造成的，如国际金融危机不是经济全球化发展的必然产物，而是金融资本过度逐利、金融监管严重缺失的结果</span></p>\n<p>【答案】ABC<span style=\"background-color: #f8cac6; color: #000000;\">材料思考题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">经济全球化可以带来巨大的分工利益，推动世界生产力的发展，即经济全球化的&ldquo;大势&rdquo;。不仅发达国家从中受益，一些发展中国家在参与经济全球化进程中也得到了快速发展。在经济全球化进程中，资金、技术等生产要素可以在国际社会流动和优化配置。</span></p>","k":"考点84 经济全球化及其影响","kid":"151","r":17503,"tot":21933},{"i":"144339","t":"多选","q":"与第二次世界大战之前的资本主义相比，当代资本主义生产关系中的社会阶层、阶级结构发生了很多新的变化，主要表现在()","o":{"A":"A.知识型和服务型劳动者数量随科技革命不断深入而持续地增加","B":"B.资本家由从前的直接生产经营者变成了以剪息票为生的食利者","C":"C.职工持股和参与决策使得劳动者成为资本家集团的重要力量","D":"D.高级职业经理成为资本主义社会大公司经营活动的实际控制者"},"a":"ABD","j":"<p>与第二次世界大战之前的资本主义相比，当代资本主义生产关系中的<span style=\"background-color: #f8cac6; color: #000000;\">社会阶层、阶级结构发生了很多新的变化</span>，<span style=\"color: #e03e2d;\">|</span><strong>主要表现在</strong>()</p>\n<p>A.知识型和服务型劳动者数量随科技革命不断深入而持续地增加&radic;</p>\n<p>B.资本家由从前的直接生产经营者变成了以剪息票为生的食利者&radic;</p>\n<p>C.职工持股和参与决策使得<strong>劳动者成为资本家集团的重要力量</strong><span style=\"color: #000000;\"> <span style=\"background-color: #f8cac6;\">这是资本家缓和劳资关系的激励制度，但并未使劳动者成为资本家，不合题意</span></span></p>\n<p>D.高级职业经理成为资本主义社会大公司经营活动的实际控制者&radic;</p>\n<p>【答案】ABD<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">知识型和服务型劳动者数量随科技革命不断深入而持续地增加。资本家由从前的直接生产经营者变成了以剪息票为生的食利者。高级职业经理成为资本主义社会大公司经营活动的实际控制者。</span></p>","k":"考点87 当代资本主义变化的新特征","kid":"156","r":11420,"tot":23153},{"i":"144340","t":"多选","q":"第二次世界大战后，由于多种社会因素的影响，资本主义发生了一系列变化。其中有些变化具有创新性和进步性，促进了社会的相对繁荣。第二次世界大战后资本主义发生变化的原因主要有()","o":{"A":"A.科学技术革命和生产力的发展","B":"B.社会主义制度初步显示的优越性","C":"C.工人阶级争取自身权利和利益斗争","D":"D.主张改良主义的政党对资本主义制度的改革"},"a":"ABCD","j":"<p>第二次世界大战后，由于多种社会因素的影响，资本主义发生了一系列变化。其中有些变化具有创新性和进步性，促进了社会的相对繁荣。<span style=\"color: #e03e2d;\">Ⅱ</span><span style=\"background-color: #f8cac6; color: #000000;\">第二次世界大战后资本主义发生变化</span>的<strong>原因主要有</strong>()</p>\n<p>A.科学技术革命和生产力的发展&radic;<span style=\"background-color: #f8cac6; color: #000000;\">为根本推动力量</span></p>\n<p>B.社会主义制度初步显示的优越性&radic;</p>\n<p>C.工人阶级争取自身权利和利益斗争&radic;</p>\n<p>D.主张改良主义的政党对资本主义制度的改革&radic;</p>\n<p>【答案】ABCD<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">第二次世界大战后资本主义发生变化的原因主要有科学技术革命和生产力的发展(根本推动力量),社会主义制度初步显示的优越性，工人阶级争取自身权利和利益斗争，主张改良主义的政党对资本主义制度的改革。</span></p>","k":"考点86 第二次世界大战后资本主义变化的原因和实质","kid":"155","r":12848,"tot":23093},{"i":"144341","t":"多选","q":"第二次世界大战后，资本主义国家为尽快恢复国民经济，在继续发挥市场机制主导性作用的同时，开始对经济进行全面干预。但是，从20世纪70年代起，随着资本主义经济陷入“滞胀”和新自由主义思潮的泛滥，西方国家普遍走上强化市场机制、弱化政府干预的道路。具体而言它们()","o":{"A":"A.保持经济稳定、提高社会福利水平","B":"B.通过国有企业私有化来提升经济竞争力","C":"C.通过福利制度改革，减少政府的财政负担","D":"D.放松对经济和金融的管制，释放经济活力"},"a":"BCD","j":"<p>第二次世界大战后，资本主义国家为尽快恢复国民经济，在继续发挥市场机制主导性作用的同时，开始对经济进行全面干预。但是，从20世纪70年代起，随着资本主义经济陷入&ldquo;滞胀&rdquo;和新自由主义思潮的泛滥，<span style=\"background-color: #f8cac6; color: #000000;\">西方国家普遍走上强化市场机制、弱化政府干预的道路</span>。<strong>具体而言它们</strong>()</p>\n<p>A.保持经济稳定、提高社会福利水平 <span style=\"background-color: #f8cac6; color: #000000;\">这是第二次世界大战后，资本主义国家对经济进行全面干预的表现，那时候，西方国家承担起了实现经济增长和充分就业、保持经济稳定、提高社会福利水平以及维护市场竞争秩序等重要职能</span></p>\n<p>B.通过国有企业私有化来提升经济竞争力&radic;</p>\n<p>C.通过福利制度改革，减少政府的财政负担&radic;</p>\n<p>D.放松对经济和金融的管制，释放经济活力&radic;</p>\n<p>【答案】BCD<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">西方国家通过国有企业私有化来提升经济竞争力，通过福利制度改革，减少政府的财政负担，放松对经济和金融的管制，释放经济活力。</span></p>","k":"考点85 第二次世界大战后资本主义变化的主要表现","kid":"153","r":6790,"tot":24706},{"i":"144342","t":"多选","q":"马克思、恩格斯在《共产党宣言》中指出：“资产阶级在它的不到一百年的阶级统治中所创造的生产力，比过去一切世代创造的全部生产力还要多，还要大。自然力的征服，机器的采用，化学在工业和农业中的应用，轮船的行驶，铁路的通行，电报的使用，整个大陆的开垦，河川的通航，仿佛用法术从地下呼唤出来的大量人口——过去哪一个世纪料想到在社会劳动里蕴藏有这样的生产力呢?”资本主义社会生产力迅速发展的主要原因是()","o":{"A":"A.资本追逐剩余价值的内在动力","B":"B.市场激烈竞争的外在压力","C":"C.无产阶级对资产阶级的斗争","D":"D.资本主义国家对市场的全面控制"},"a":"AB","j":"<p>马克思、恩格斯在《共产党宣言》中指出：&ldquo;资产阶级在它的不到一百年的阶级统治中所创造的生产力，比过去一切世代创造的全部生产力还要多，还要大。自然力的征服，机器的采用，化学在工业和农业中的应用，轮船的行驶，铁路的通行，电报的使用，整个大陆的开垦，河川的通航，仿佛用法术从地下呼唤出来的大量人口&mdash;&mdash;过去哪一个世纪料想到在社会劳动里蕴藏有这样的生产力呢?&rdquo;<span style=\"color: #e03e2d;\">||</span><span style=\"background-color: #f8cac6; color: #000000;\">资本主义社会生产力迅速发展</span>的<strong>主要原因是</strong>()</p>\n<p>A.资本追逐剩余价值的内在动力&radic;</p>\n<p>B.市场激烈竞争的外在压力&radic;</p>\n<p>C.无产阶级对资产阶级的斗争 <span style=\"background-color: #f8cac6; color: #000000;\">这是资本主义必然被社会主义所代替的原因之一</span></p>\n<p>D.资本主义国家对市场的<strong>全面控制 </strong><span style=\"background-color: #f8cac6; color: #000000;\">即便是二战后资本主义国家对经济进行的也是&ldquo;全面干预&rdquo;,不是控制</span></p>\n<p>【答案】AB<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">与封建社会相比，资本主义显示了巨大的历史进步性。资本追求剩余价值的内在动力和竞争的外在压力推动了社会生产力的迅速发展。</span></p>","k":"考点89 资本主义的历史地位","kid":"719","r":9387,"tot":23940},{"i":"144343","t":"多选","q":"资本主义社会同历史上有过的一切其他社会制度一样，其产生、发展以及最终为另一种更高级的社会制度所代替，都是由人类社会发展的一般规律决定的，是客观的不以人的意志为转移的自然历史过程。但同此前的其他社会制度相比，资本主义制度空前地提高了社会生产力，则是以往任何社会所不可比拟的。与封建社会相比，资本主义巨大的历史进步性在于()","o":{"A":"A.资本主义将科学技术转变为强大的生产力","B":"B.资本追求剩余价值的内在动力和竞争的外在压力推动了社会生产力的迅速发展","C":"C.资本主义上层建筑促进和完善其生产方式，推动了社会生产力的迅速发展和社会进步","D":"D.资本主义社会存在着资产阶级和无产阶级两大阶级之间的矛盾和斗争"},"a":"ABC","j":"<p>资本主义社会同历史上有过的一切其他社会制度一样，其产生、发展以及最终为另一种更高级的社会制度所代替，都是由人类社会发展的一般规律决定的，是客观的不以人的意志为转移的自然历史过程。但同此前的其他社会制度相比，资本主义制度空前地提高了社会生产力，则是以往任何社会所不可比拟的。<span style=\"color: #e03e2d;\">|</span><span style=\"background-color: #f8cac6; color: #000000;\">与封建社会相比，资本主义巨大的历史进步性</span><strong>在于</strong>()</p>\n<p>A.资本主义将科学技术转变为强大的生产力&radic;</p>\n<p>B.资本追求剩余价值的内在动力和竞争的外在压力推动了社会生产力的迅速发展&radic;</p>\n<p>C.资本主义上层建筑促进和完善其生产方式，推动了社会生产力的迅速发展和社会进步&radic;</p>\n<p>D.资本主义社会存在着资产阶级和无产阶级两大阶级之间的矛盾和斗争 <span style=\"background-color: #f8cac6; color: #000000;\">这不是与封建社会相比的资本主义的巨大历史进步性，而是被社会主义取代的必然原因之一</span></p>\n<p>【答案】ABC<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">资本主义将科学技术转变为强大的生产力资本追求剩余价值的内在动力和竞争的外在压力推动了社会生产力的迅速发展，资本主义上层建筑促进和完善其生产方式，推动了社会生产力的迅速发展和社会进步。</span></p>","k":"考点89 资本主义的历史地位","kid":"719","r":15432,"tot":22299}]};
